"""Select native inverse stages without rewriting immutable accepted history."""
from __future__ import annotations

from ._collections import AcceptedRecords
from ._command_state import CommandError, equal


def _commands(entry):
    recorder = entry.get('records')
    if not isinstance(recorder, dict) or not isinstance(recorder.get('commands'), list):
        raise CommandError('complete accepted command history is required', kind='history_unavailable')
    commands = recorder['commands']
    if not commands or any(not isinstance(record, dict) or record.get('ordinal') != ordinal
                           or any(not isinstance(record.get(key), list)
                                  for key in ('writes', 'reads', 'selections', 'created'))
                           for ordinal, record in enumerate(commands)):
        raise CommandError('accepted command ordinals are incomplete', kind='history_unavailable')
    return commands


def _steps(entry, *, required=False):
    commands = _commands(entry)
    steps = entry['records'].get('steps')
    if steps is None and not required:
        # Historical native captures still support their existing whole inverse.
        # They supply no authority to select or invent a historical step.
        return [(None, commands, [])]
    if not isinstance(steps, list) or not steps:
        raise CommandError('accepted step history is unavailable', kind='history_unavailable')
    cursor, seen, result = 0, set(), []
    for step in steps:
        if not isinstance(step, dict):
            raise CommandError('accepted step history is malformed', kind='history_unavailable')
        identity, ordinals = step.get('id'), step.get('command_ordinals')
        if (not isinstance(identity, str) or not identity or identity in seen
                or not isinstance(ordinals, list) or not ordinals
                or any(type(index) is not int for index in ordinals)
                or ordinals != list(range(cursor, cursor + len(ordinals)))
                or cursor + len(ordinals) > len(commands)
                or not isinstance(step.get('patch'), list)
                or not isinstance(step.get('dependencies', []), list)):
            raise CommandError('accepted steps do not partition command history', kind='history_unavailable')
        seen.add(identity)
        cursor += len(ordinals)
        result.append((step, [commands[index] for index in ordinals], step.get('dependencies', [])))
    if cursor != len(commands):
        raise CommandError('accepted steps omit command history', kind='history_unavailable')
    return result


class SelectedRecords(AcceptedRecords):
    """A source-preserving view; entries and command ordinals stay authoritative."""

    def __init__(self, accepted, chosen, address_resolver):
        self.accepted, self.chosen = accepted, chosen
        self.address_resolver = address_resolver
        selected = [record for entry in accepted.entries for record in entry_records(accepted, entry)
                    if record['ordinal'] in chosen[entry['publication_id']]]
        super().__init__(accepted.entries, selected, accepted.load_boundary)

    def selected_for(self, entry):
        ordinals = self.chosen[entry['publication_id']]
        return [record for record in entry_records(self.accepted, entry) if record['ordinal'] in ordinals]

    def boundary(self, record):
        return self.accepted.boundary(record)


def entry_records(records, entry):
    """Return selected captures while retaining complete boundary source entries."""
    if isinstance(records, SelectedRecords):
        return records.selected_for(entry)
    offset = 0
    for source in records.entries:
        count = len(source['records']['commands'])
        if source is entry:
            result = records[offset:offset + count]
            if not equal(result, source['records']['commands']):
                break
            return result
        offset += count
    raise CommandError('inverse records differ from accepted history', kind='history_unavailable')


def select_inverse_records(accepted, steps=None, *, address_resolver=None):
    """Select only authenticated command runs; step effect patches are never run."""
    if not isinstance(accepted, AcceptedRecords) or isinstance(accepted, SelectedRecords):
        raise CommandError('inverse selection needs complete accepted records', kind='history_unavailable')
    originals = [record for entry in accepted.entries for record in _commands(entry)]
    if not equal(list(accepted), originals):
        raise CommandError('inverse records differ from accepted history', kind='history_unavailable')
    publications = [entry['publication_id'] for entry in accepted.entries]
    if not publications or len(set(publications)) != len(publications):
        raise CommandError('inverse target history is incomplete', kind='history_unavailable')
    if steps is not None and (not isinstance(steps, dict) or set(steps) != set(publications)):
        raise CommandError('inverse steps must specify every target publication', kind='invalid_steps')
    chosen = {}
    for entry in accepted.entries:
        publication = entry['publication_id']
        groups = _steps(entry, required=steps is not None)
        if steps is None:
            chosen[publication] = {record['ordinal'] for _, commands, _ in groups for record in commands}
            continue
        requested = steps[publication]
        if (not isinstance(requested, list) or not requested
                or any(not isinstance(identity, str) or not identity for identity in requested)
                or len(set(requested)) != len(requested)
                or not set(requested) <= {step['id'] for step, _, _ in groups}):
            raise CommandError('inverse step IDs must be known and unique', kind='invalid_steps')
        chosen[publication] = {record['ordinal'] for step, commands, _ in groups
                               if step['id'] in requested for record in commands}
    return SelectedRecords(accepted, chosen, address_resolver)


def selected_dependencies(records):
    if not isinstance(records, AcceptedRecords):
        return []
    if not equal(list(records), [record for entry in records.entries for record in entry_records(records, entry)]):
        raise CommandError('inverse selection differs from accepted history', kind='history_unavailable')
    result = []
    for entry in records.entries:
        selected = {record['ordinal'] for record in entry_records(records, entry)}
        for _, commands, dependencies in _steps(entry):
            if any(record['ordinal'] in selected for record in commands):
                result.extend(dependencies)
    return result


def inverse_stages(records):
    """Yield reverse execution groups with their original immutable step IDs."""
    if not isinstance(records, AcceptedRecords):
        for record in reversed(records):
            yield None, None, [record]
        return
    for entry in reversed(records.entries):
        commands = {record['ordinal']: record for record in entry_records(records, entry)}
        for step, originals, _ in reversed(_steps(entry)):
            chosen = [commands[record['ordinal']] for record in originals if record['ordinal'] in commands]
            if chosen:
                nested = ([binding for binding in chosen[0].get('bindings', [])
                           if binding['key'] == 'inverse.stage'] if len(chosen) == 1
                          and chosen[0]['command']['op'] == 'timeline.inverse' else [])
                if not nested:
                    yield entry.get('publication_id'), step['id'] if step is not None else None, chosen
                    continue
                record = chosen[0]
                cursor = 0
                effect_cursor = 0
                for binding in nested:
                    boundary = binding['boundary']
                    start, end = boundary['native_write_range']
                    first, last = boundary['effect_range']
                    if (binding['ref'] != 'parent' or binding['policy'] != 'fixed'
                            or binding['dependencies'] != []
                            or boundary['publication_id'] not in record['command']['args']['publications']
                            or start != cursor or not start < end <= len(record['writes'])
                            or first != effect_cursor or not first < last <= len(step['patch'])
                            or record.get('derived_writes')):
                        raise CommandError('nested inverse ranges differ from accepted history',
                                           kind='history_unavailable')
                    cursor, effect_cursor = end, last
                if cursor != len(record['writes']) or effect_cursor != len(step['patch']):
                    raise CommandError('nested inverse ranges omit accepted history', kind='history_unavailable')
                for binding in reversed(nested):
                    start, end = binding['boundary']['native_write_range']
                    yield entry['publication_id'], step['id'], [{**record, 'writes': record['writes'][start:end]}]


def _causal_commands(entry, commands):
    """Project causal compiler ownership without rewriting accepted captures."""
    originals = entry['records']['commands']
    for source in originals:
        for write in source.get('derived_writes', []):
            cause = write.get('cause', source['ordinal'])
            if type(cause) is not int or not 0 <= cause <= source['ordinal']:
                raise CommandError('compiler effect cause is unavailable', kind='history_unavailable')
    return [{**record, 'derived_writes': [write for source in originals
        for write in source.get('derived_writes', [])
        if write.get('cause', source['ordinal']) == record['ordinal']]}
        for record in commands]


def _check_groups(groups, *, state, address_resolver):
    from .inverse import check_intervening

    for index, (commands, dependencies, active) in enumerate(groups):
        if not active:
            continue
        later = [group for group in groups[index + 1:] if not group[2]]
        check_intervening(commands, [record for group in later for record in group[0]],
                          include_dependents=True, state=state, dependencies=dependencies,
                          later_dependencies=[dependency for group in later for dependency in group[1]],
                          address_resolver=address_resolver)


def check_step_dependents(records, *, state=None):
    """Recheck same-publication consumers at every inverse execution boundary."""
    if not isinstance(records, SelectedRecords):
        return
    for entry in records.entries:
        chosen = records.chosen[entry['publication_id']]
        groups = [(_causal_commands(entry, commands), dependencies, any(record['ordinal'] in chosen for record in commands))
                  for _, commands, dependencies in _steps(entry)]
        _check_groups(groups, state=state, address_resolver=records.address_resolver)


def check_later_steps(selected, history, *, state=None, address_resolver=None):
    """Check each selected step against its own complete, unselected suffix.

    The provider authenticates ancestry before calling this helper. A gap before
    a newer selected target belongs to that target's input, not its later tail.
    """
    if not isinstance(selected, SelectedRecords) or history is None:
        raise CommandError('inverse scan needs selected accepted history', kind='history_unavailable')
    selected_dependencies(selected)
    address_resolver = address_resolver or selected.address_resolver
    groups, found = [], []
    previous = None
    for entry in history:
        publication = entry['publication_id']
        if previous is not None and entry.get('previous') != previous:
            raise CommandError('inverse history is not contiguous', kind='history_unavailable')
        previous = {key: entry[key] for key in ('revision_id', 'publication_id')}
        source = next((source for source in selected.entries if source['publication_id'] == publication), None)
        if source is not None:
            if not equal(source, entry):
                raise CommandError('inverse target differs from accepted history', kind='history_unavailable')
            found.append(publication)
        chosen = selected.chosen.get(publication, set())
        for step, commands, dependencies in _steps(entry):
            active = any(record['ordinal'] in chosen for record in commands)
            groups.append((_causal_commands(entry, commands), dependencies, active))
    if found != [entry['publication_id'] for entry in selected.entries]:
        raise CommandError('inverse scan omits accepted targets', kind='history_unavailable')
    _check_groups(groups, state=state, address_resolver=address_resolver)

runtime/runtime_protocol/timeline_commit.text:
"""Authenticate provider annotations against sealed requests and recorded boundaries.

This module consumes provider observations; it never executes submitted edits.
Command execution, conflict detection and inverse construction belong to Agent.
"""
from __future__ import annotations

import copy
import hashlib
import re

from .timeline_commit_producer import value_equal
from .timeline_commit_validation import digest
from .util import canonical_json


def require(condition, message):
    if not condition:
        from .timeline_commit_store import reject
        reject("invalid_records", message, status=422)


def images(document):
    return {"parent": document["parent_revision"], **{
        "shot-revision:" + row["revision_id"]: row for row in document["shot_revisions"]}, **{
        "internal-revision:" + row["revision_id"]: row for row in document["internal_timeline_revisions"]}}


def normalized_path(ref, path):
    if ref == "parent" and path[:1] in (["clips"], ["registry"]):
        return ["config", *path]
    return list(path)


_TEXT_BINDING_REF = re.compile(
    r"occurrence:([^/]+)/text-binding:(prompt|voiceover_script|transcript)"
    r"(?::([a-z][a-z0-9-]{0,63}))?\Z"
)


def _text_binding_key(kind, slot):
    return kind + (":" + slot if slot is not None else "")


def _text_binding_members(owner, rows):
    require(isinstance(rows, list), "provider text-binding collection is absent or malformed")
    members = []
    for row in rows:
        require(isinstance(row, dict) and isinstance(row.get("kind"), str)
                and (row.get("slot") is None or isinstance(row.get("slot"), str)),
                "provider text-binding collection has an invalid identity")
        member = owner + "/text-binding:" + _text_binding_key(row["kind"], row.get("slot"))
        require(member not in members, "provider text-binding collection has an ambiguous identity")
        members.append(member)
    return members


def _text_binding_site(boundary, ref):
    collection = ref.endswith("/collection:text-binding")
    if collection:
        owner = ref.removesuffix("/collection:text-binding")
        owner_match = re.fullmatch(r"occurrence:([^/]+)", owner)
        require(owner_match is not None, "provider text-binding collection is outside its authenticated boundary")
        if owner_match is None:
            raise AssertionError("unreachable text-binding collection alias")
        occurrence, kind, slot = owner_match.group(1), None, None
    else:
        match = _TEXT_BINDING_REF.fullmatch(ref)
        require(match is not None, "provider text-binding alias is outside its authenticated boundary")
        if match is None:
            raise AssertionError("unreachable text-binding alias")
        occurrence, kind, slot = match.groups()
        require(kind == "prompt" or slot is None,
                "provider text-binding alias has an invalid slot")
    owner = "occurrence:" + occurrence
    rows = boundary.get("parent", {}).get("payload", {}).get("occurrences", [])
    matches = [row for row in rows if isinstance(row, dict) and row.get("occurrence_id") == occurrence]
    require(len(matches) == 1, "provider text-binding occurrence is outside or ambiguous in its boundary")
    shot_ref = "shot-revision:" + str(matches[0].get("shot_revision_id"))
    require(shot_ref in boundary, "provider text-binding occurrence has no authenticated shot")

    bindings = boundary[shot_ref]["payload"].get("text_bindings", [])
    require(isinstance(bindings, list),
            "provider text-binding collection is malformed")
    for row in bindings:
        require(isinstance(row, dict) and row.get("kind") in {"prompt", "voiceover_script", "transcript"}
                and (row.get("slot") is None or isinstance(row.get("slot"), str)),
                "provider text-binding collection has an invalid identity")
    if collection:
        _text_binding_members(owner, bindings)
        return shot_ref, ["text_bindings"]
    identity = _text_binding_key(kind, slot)
    matching = [row for row in bindings
                if _text_binding_key(row["kind"], row.get("slot")) == identity]
    require(len(matching) <= 1, "provider text-binding alias is ambiguous in its boundary")
    return shot_ref, ["text_bindings", "kind:" + identity]


def site(boundary, ref, path, continuations=None):
    """Resolve root and native aliases in one authenticated closure image."""
    path = list(path)
    if ref == "timeline":
        return ref, []
    if ref in boundary:
        return ref, normalized_path(ref, path)
    if ref.startswith(("shot-revision:", "internal-revision:")) and continuations:
        seen = set()
        while ref not in boundary and ref in continuations and ref not in seen:
            seen.add(ref)
            successors = continuations[ref]
            require(len(successors) == 1, "provider source has ambiguous authenticated successors")
            ref = next(iter(successors))
        if ref in boundary:
            return ref, path
    if "/text-binding:" in ref:
        binding_ref, binding_path = _text_binding_site(boundary, ref)
        return binding_ref, [*binding_path, *path]
    if "/collection:" in ref:
        owner, family = ref.rsplit("/collection:", 1)
        if family == "text-binding":
            return _text_binding_site(boundary, owner + "/collection:text-binding")
        if family == "asset":
            require(owner == "parent",
                    "provider collection alias is outside its authenticated boundary")
            # The native asset collection is a shape guard over the complete
            # parent image.  Its recorder state includes both authored registry
            # mirrors, so it must retain the parent root as its physical site.
            return "parent", []
        if family in {"clip", "track", "occurrence"}:
            prefix = ["config", family + "s"] if owner == "parent" and family != "occurrence" else [family + "s"]
            return site(boundary, owner if owner == "parent" else owner + "/source", prefix)
        require(False, "provider collection alias is outside its authenticated boundary")
    kind, _, identity = ref.partition(":")
    field = {"shot": "shot_id", "internal": "timeline_id"}.get(kind)
    if field and "/" not in identity:
        matches = [key for key, image in boundary.items() if image.get(field) == identity]
        require(len(matches) == 1, "provider alias is outside or ambiguous in its boundary")
        return matches[0], path[1:] if path[:1] == ["payload"] else path
    owner, _, entity = ref.partition("/")
    if owner == "parent":
        if entity == "source":
            return "parent", ["config", *path]
        if entity == "registry":
            return "parent", ["config", "registry", *path]
        if entity.startswith(("clip:", "track:")):
            family, identity = entity.split(":", 1)
            return "parent", ["config", family + "s", "id:" + identity, *path]
        if entity.startswith("asset:"):
            return "parent", ["config", "registry", "assets", entity[6:], *path]
    if owner.startswith("occurrence:"):
        identity = owner[len("occurrence:"):]
        if not entity:
            return "parent", ["occurrences", "occurrence_id:" + identity, *path]
        rows = boundary["parent"]["payload"]["occurrences"]
        matches = [row for row in rows if row["occurrence_id"] == identity]
        require(len(matches) == 1, "provider occurrence alias is outside its boundary")
        shot_ref = "shot-revision:" + matches[0]["shot_revision_id"]
        require(shot_ref in boundary, "provider occurrence has no authenticated shot")
        if entity == "shot":
            return shot_ref, path[1:] if path[:1] == ["payload"] else path
        internal = "internal-revision:" + boundary[shot_ref]["internal_timeline_revision_id"]
        require(internal in boundary, "provider occurrence has no authenticated internal timeline")
        if entity == "source":
            return internal, path
        if entity == "registry":
            return internal, ["registry", *path]
        if entity.startswith(("clip:", "track:")):
            family, identity = entity.split(":", 1)
            return internal, [family + "s", "id:" + identity, *path]
        if entity.startswith("asset:"):
            return internal, ["registry", "assets", entity[6:], *path]
    require(False, "provider alias is outside its authenticated boundary")


def location(payload, path, *, absent_items=False):
    node = payload
    for index, token in enumerate(path):
        if isinstance(node, list):
            if index and path[index - 1] == "text_bindings" and token.startswith("kind:"):
                identity = token.removeprefix("kind:")
                matches = [row for row in node if isinstance(row, dict)
                           and _text_binding_key(row.get("kind"), row.get("slot")) == identity]
                require(len(matches) <= 1, "provider observation has an ambiguous text-binding path")
                if not matches:
                    return {"state": "absent"}
                node = matches[0]
                continue
            key, separator, identity = token.partition(":")
            matches = [row for row in node if isinstance(row, dict) and row.get(key) == identity]
            if absent_items and separator and not matches:
                return {"state": "absent"}
            require(separator and len(matches) == 1, "provider observation has an ambiguous item path")
            node = matches[0]
        elif isinstance(node, dict) and token in node:
            node = node[token]
        else:
            return {"state": "absent"}
    return {"state": "present", "value": node}


def stored_path(payload, ref, path):
    if (ref == "parent" and path[:2] in (["config", "clips"], ["config", "registry"])
            and path[1] not in payload.get("config", {}) and path[1] in payload):
        return path[1:]
    return path


def normalized(boundary, value, continuations=None):
    ref, path = site(boundary, value["ref"], value["path"], continuations)
    return {**value, "ref": ref, "path": path}


def native_site(boundary, ref, path):
    if ref.startswith("occurrence:") and ref.endswith("/shot") and path[:1] != ["payload"]:
        return site(boundary, ref.removesuffix("/shot"), path)
    if ref.startswith("shot:") and "/" not in ref and path[:1] != ["payload"]:
        return "timeline", []
    return site(boundary, ref, path)


def covers(dependencies, read):
    for dependency in dependencies:
        if value_equal(dependency, read):
            return True
        if dependency["kind"] == "scope" and (
                dependency["ref"] == "timeline" or dependency["ref"] == read["ref"]
                and read["path"][:len(dependency["path"])] == dependency["path"]):
            return True
    return False


def validate_read(boundary, read, continuations=None):
    read = normalized(boundary, read, continuations)
    if read["kind"] == "scope":
        return read
    payload = boundary[read["ref"]]["payload"]
    observed = location(payload, stored_path(payload, read["ref"], read["path"]))
    if read["kind"] == "field":
        require(value_equal(observed, read["state"]), "declared field read differs from its input boundary")
    else:
        rows = observed.get("value")
        if not isinstance(rows, list):
            require(False, "declared collection is absent at its input boundary")
            return read
        key = "occurrence_id" if read["path"][-1:] == ["occurrences"] else "id"
        members = [row[key] for row in rows if isinstance(row, dict) and isinstance(row.get(key), str)]
        require(len(members) == len(rows)
                and sorted(members) == read["members"]
                and (read["order"] is None or members == read["order"]),
                "declared collection read differs from its input boundary")
    return read


def _omitted_inverse_created_is_authenticated(submitted, record, records):
    """Allow the inverse provider to report restored allocation facts.

    ``created`` is optional on the wire.  A raw inverse request therefore has
    no caller allocation claim, while the provider must still return the
    authenticated restoration facts in its record.  This helper only admits
    that request/recorder shape; the physical bindings, materialization,
    destination, history, and undo guards below and in the store remain the
    authority for the restored identities.
    """
    if "created" in submitted or submitted.get("op") != "timeline.inverse":
        return False
    args = submitted.get("args")
    command = record["command"]
    created = command.get("created")
    if not isinstance(args, dict) or not isinstance(created, list) or not created:
        return False
    if records.get("undo_of") != args.get("publications"):
        return False
    requested_steps = args.get("steps")
    if records.get("undo_steps") != requested_steps:
        return False
    facts = record["created"]
    if not isinstance(facts, list) or [item["ref"] for item in facts] != created:
        return False
    restoration_writes = {
        write["ref"]
        for write in [*record["writes"], *record["derived_writes"]]
        if write["path"] == []
        and write["before"] == {"state": "absent"}
        and write["after"]["state"] == "present"
    }
    return set(created) <= restoration_writes


def validate_claims(request, records):
    commands = records["commands"]
    require(len(commands) == len(request["commands"]), "provider command count differs from request")
    for submitted, record in zip(request["commands"], commands):
        core_matches = all(value_equal(submitted.get(key), record["command"].get(key))
                           for key in ("schema_version", "op", "version", "select", "args"))
        created_matches = value_equal(submitted.get("created", []), record["command"].get("created", []))
        inverse_restoration = _omitted_inverse_created_is_authenticated(submitted, record, records)
        require(core_matches and (created_matches or inverse_restoration),
                "provider executed a different command")


def _authoring_identity(kind, *parts):
    encoded = "\0".join([kind, *(canonical_json(part) for part in parts)]).encode("utf-8")
    return f"{kind}-" + hashlib.sha256(encoded).hexdigest()


def validate_step(request, records, step, boundary, batch_reads, continuations, command_inputs=None):
    submitted = next((item for item in request.get("steps", []) if item["id"] == step["id"]), None)
    dependencies = step["dependencies"]
    for read in [*batch_reads, *(validate_read(boundary, read, continuations) for read in (submitted or {}).get("reads", []))]:
        require(covers(dependencies, read), "provider dependency union omits a declared read")
    for ordinal in step["command_ordinals"]:
        record = records["commands"][ordinal]
        command_boundary = (command_inputs or {}).get(ordinal, boundary)
        created = {item["ref"] for item in record["created"]}
        for read in record["reads"]:
            if read["ref"] in created and read["state"] == {"state": "absent"}:
                continue
            ref, path = native_site(command_boundary, read["ref"], read["path"])
            if ref == "timeline" or not path or "/collection:" in read["ref"]:
                capture = {"kind": "scope", "ref": ref, "path": []}
                if "/collection:" in read["ref"] and ref != "timeline":
                    observed = location(command_boundary[ref]["payload"], path).get("value")
                    if isinstance(observed, list):
                        if read["ref"].endswith("/collection:text-binding"):
                            owner = read["ref"].rsplit("/collection:", 1)[0]
                            members = _text_binding_members(owner, observed)
                        else:
                            key = "occurrence_id" if path[-1:] == ["occurrences"] else "id"
                            members = [row[key] for row in observed]
                        capture = {"kind": "collection", "ref": ref, "path": path,
                                   "members": sorted(members), "order": members}
            else:
                capture = {"kind": "field", "ref": ref, "path": path, "state": read["state"]}
            require(covers(dependencies, capture), "provider dependency union omits a captured read")
        for binding in record["bindings"]:
            if "dependency" in binding:
                require(covers(dependencies, binding["dependency"]), "provider dependency union omits a bound read")
    assertions = (submitted or {}).get("patch", [])
    calls = [request["commands"][ordinal] for ordinal in step["command_ordinals"]]
    patches = [change for call in calls if call["op"] == "doc.patch" for change in call["args"]["changes"]]
    if submitted is not None and all(call["op"] == "doc.patch" for call in calls):
        require(value_equal(assertions, patches), "submitted step patch differs from its commands")
    for claim in assertions:
        claim = normalized(boundary, claim, continuations)
        require(any(value_equal(claim, {**effect, "path": normalized_path(effect["ref"], effect["path"])})
                    for effect in step["patch"])
                or any(value_equal(claim, {**binding["change"], "path": binding["path"]})
                       for ordinal in step["command_ordinals"] if records["commands"][ordinal]["command"]["op"] == "doc.patch"
                       for binding in records["commands"][ordinal]["bindings"]
                       if "change" in binding), "provider effects omit a submitted assertion")


def validate_bindings(request, records, expected, boundary, output, step, ordinal, continuations, original,
                      step_input, effect_boundaries=None, input_parent_revision=None):
    record = records["commands"][ordinal]
    for binding in record["bindings"]:
        if "physical_ref" not in binding:
            continue  # Original ABI-1 captures do not claim physical provenance.
        captured = binding.get("boundary", {})
        phase = captured.get("phase")
        require(phase in {"input", "batch-read", "effect"} and (phase != "batch-read" or ordinal == 0)
                and captured.get("base_revision_id") == request["base_revision_id"]
                and captured.get("base_publication_id") == request["base_publication_id"]
                and value_equal(captured.get("evaluated_head"), expected)
                and captured.get("step_id") == step["id"]
                and captured.get("command_ordinal") == ordinal,
                "provider binding boundary differs from the authenticated invocation")
        bound = boundary
        if phase == "effect":
            side, index = captured.get("side"), binding.get("effect_ordinal")
            require(binding["key"] == "commit.effect" and side in {"before", "after"}
                    and ordinal == step["command_ordinals"][-1]
                    and type(index) is int and 0 <= index < len(step["patch"]),
                    "provider effect binding is misattributed")
            require(step["patch"][index]["ref"] == binding["physical_ref"]
                    and step["patch"][index]["path"] == binding.get("path"),
                    "provider effect binding differs from the recorded effect")
            if effect_boundaries is not None:
                require(index in effect_boundaries,
                        "provider effect binding is outside an authenticated inverse stage")
                bound = effect_boundaries[index][0 if side == "before" else 1]
            else:
                bound = step_input if side == "before" else output
        elif binding["key"] == "commit.materialization":
            bound = step_input
        for key in ("command_ordinal", "step_id", "phase", "change_ordinal"):
            if key in binding:
                require(binding[key] == captured.get(key), "provider binding attribution is inconsistent")
        physical = binding["physical_ref"]
        resolve = site if binding["key"].startswith(("doc.patch:", "commit.")) else native_site
        ref, _ = (site(bound, binding["ref"], [], continuations) if resolve is site
                  else resolve(bound, binding["ref"], []))
        require(ref == physical or ref == "timeline" and binding["key"] in {"commit.read", "commit.atomic"},
                "provider alias names a different physical image")
        # Materialization observes the authenticated landing input, whose
        # physical sources can already be successors of the requested base.
        # Its owner/edge correspondence is verified below. Submitted aliases
        # still have to retain their original physical source.
        if (ordinal == 0 and phase != "effect" and resolve is site and binding["ref"] != "timeline"
                and binding["key"] != "commit.materialization"):
            original_ref, _ = site(original, binding["ref"], [], continuations)
            continued_ref, _ = site(bound, original_ref, [], continuations)
            require(continued_ref == physical, "provider alias changed without an authenticated successor")
        image = bound.get(physical)
        revision_matches = image is not None and binding.get("revision_id") == image["revision_id"]
        if (not revision_matches and image is not None and physical == "parent"
                and phase == "effect" and captured.get("side") == "before"
                and effect_boundaries is None and input_parent_revision is not None):
            # Agent hydrates captured documents before deriving effect images.
            # Equal payloads alone cannot authorize a different parent pin.
            revision_matches = binding.get("revision_id") == input_parent_revision
        require(image is not None and binding.get("content_digest") == image["content_digest"]
                and revision_matches,
                "provider binding differs from its authenticated input image")
        if "owners" in binding:
            owners = []
            for row in bound["parent"]["payload"]["occurrences"]:
                shot_ref = "shot-revision:" + row["shot_revision_id"]
                shot = bound.get(shot_ref)
                if physical == shot_ref or shot is not None and physical == "internal-revision:" + shot["internal_timeline_revision_id"]:
                    owners.append("occurrence:" + row["occurrence_id"] + "/shot")
            require(set(owners) == set(binding["owners"]), "provider binding owners differ from its physical edges")
        if "change" in binding:
            change = binding["change"]
            require(change["ref"] == physical and normalized_path(physical, change["path"]) == binding.get("path"),
                    "provider binding path differs from its change")
            start, end = binding.get("write_range", [-1, -1])
            require(0 <= start <= end <= len(record["writes"]), "provider binding has an invalid write range")
            if record["command"]["op"] == "doc.patch":
                index = captured.get("change_ordinal")
                changes = request["commands"][ordinal]["args"]["changes"]
                require(type(index) is int and 0 <= index < len(changes)
                        and value_equal(normalized(boundary, changes[index], continuations), normalized(boundary, change)),
                        "provider binding differs from the submitted change")
        if "dependency" in binding:
            dependency = binding["dependency"]
            require(dependency["ref"] == physical and dependency["path"] == binding.get("path"),
                    "provider read binding differs from its dependency")
        if "successor" in binding:
            from .timeline_materialization import edges
            before_rows, after_rows = edges({"parent_revision": boundary["parent"]}), edges({"parent_revision": output["parent"]})
            owner = binding.get("owner", "").removeprefix("occurrence:").removesuffix("/shot")
            successor = binding["successor"]
            require(binding["key"] == "commit.materialization" and owner in before_rows and owner in after_rows
                    and successor in output, "provider successor lacks an authenticated owner edge")
            before_shot = "shot-revision:" + before_rows[owner][1]
            after_shot = "shot-revision:" + after_rows[owner][1]
            require(before_shot in boundary and after_shot in output, "provider successor has an absent owner image")
            before_internal = "internal-revision:" + boundary[before_shot]["internal_timeline_revision_id"]
            after_internal = "internal-revision:" + output[after_shot]["internal_timeline_revision_id"]
            require((physical, successor, binding.get("edge_before"), binding.get("edge_after")) in {
                (before_shot, after_shot, before_internal, after_internal),
                (before_internal, after_internal, before_shot, after_shot)},
                "provider successor differs from its authenticated physical edges")


def project_observation(payload, path, state):
    """Project a recorder's full observed value, without interpreting edit operands."""
    if not path:
        require(state["state"] == "present", "provider removed an existing payload")
        return copy.deepcopy(state["value"])
    result = copy.deepcopy(payload)
    node = result
    for token in path[:-1]:
        if isinstance(node, list):
            key, _, identity = token.partition(":")
            matches = [row for row in node if row.get(key) == identity]
            require(len(matches) == 1, "provider observation has no unique ancestor")
            node = matches[0]
        else:
            require(isinstance(node, dict) and token in node, "provider observation has no ancestor")
            node = node[token]
    token = path[-1]
    if isinstance(node, list):
        key, _, identity = token.partition(":")
        indices = [index for index, row in enumerate(node) if row.get(key) == identity]
        require(len(indices) <= 1, "provider observation has an ambiguous item")
        if state["state"] == "absent":
            require(bool(indices), "provider removed an absent item")
            node.pop(indices[0])
        elif indices:
            node[indices[0]] = copy.deepcopy(state["value"])
        else:
            node.append(copy.deepcopy(state["value"]))
    else:
        require(isinstance(node, dict), "provider observation has a scalar ancestor")
        if state["state"] == "absent":
            node.pop(token, None)
        else:
            node[token] = copy.deepcopy(state["value"])
    return result


def _physical_owner(document, ref):
    """Return the occurrence owning an authenticated shot/internal image."""
    parent = document.get("parent", {}).get("payload", {})
    for row in parent.get("occurrences", []):
        occurrence = row.get("occurrence_id")
        shot_ref = "shot-revision:" + str(row.get("shot_revision_id"))
        if ref == shot_ref:
            return occurrence, row.get("shot_id")
        shot = document.get(shot_ref, {})
        if ref == "internal-revision:" + str(shot.get("internal_timeline_revision_id")):
            return occurrence, row.get("shot_id")
    return None


def _coherent_materialization(boundary, effect, effects):
    """Accept a physical turnover only when its sibling effect names its owner."""
    if not effects:
        return False
    parent = boundary.get("parent", {}).get("payload", {})
    occurrences = {row.get("occurrence_id"): row for row in parent.get("occurrences", [])}
    roots = [candidate for candidate in effects
             if not normalized_path(candidate["ref"], candidate["path"])
             and candidate["ref"].startswith("shot-revision:")]

    def payload(effect):
        if effect["op"] == "remove":
            value = effect.get("before")
            return value.get("value") if value.get("state") == "present" else None
        return effect.get("value")

    def shot_ids(image):
        return {binding.get("shot_id") for binding in (image or {}).get("text_bindings", [])
                if binding.get("shot_id") is not None}

    if effect["ref"] == "parent" and effect["path"][-1:] == ["shot_revision_id"]:
        occurrence = next((part.split(":", 1)[1] for part in effect["path"]
                           if part.startswith("occurrence_id:")), None)
        row = occurrences.get(occurrence)
        if row is None:
            return False
        return any(effect.get("value") == root["ref"].partition(":")[2]
                   and row.get("shot_id") in shot_ids(payload(root)) for root in roots)

    if effect["ref"].startswith(("shot-revision:", "internal-revision:")) and not effect["path"]:
        internal_id = effect["ref"].partition(":")[2]
        if effect["ref"].startswith("shot-revision:"):
            image = payload(effect) or {}
            internal_id = image.get("internal_timeline_revision_id")
        if internal_id is None:
            return False
        return any(root_payload.get("internal_timeline_revision_id") == internal_id
                   and any(row.get("shot_id") in shot_ids(root_payload) for row in occurrences.values())
                   for root in roots for root_payload in [payload(root) or {}])
    return False


def _materialization_input(boundary, original, effect, observed_path, effects=None):
    """Accept a rebased physical edge only across one authenticated owner."""
    if original is None:
        return False
    ref, path = effect["ref"], normalized_path(effect["ref"], effect["path"])
    if ref == "parent" and path[-1:] == ["shot_revision_id"]:
        owner_path = path[:-1]
        original_value = location(original[ref]["payload"], path)
        if original_value.get("state") != "present":
            return False
        owner = owner_path[-1].partition(":")[2] if owner_path[-1].startswith("occurrence_id:") else None
        current_value = location(boundary[ref]["payload"], path)
        if owner is None or current_value.get("state") != "present":
            return False
        old_ref = "shot-revision:" + str(original_value["value"])
        current_ref = "shot-revision:" + str(current_value["value"])
        old_owner = _physical_owner(original, old_ref)
        current_owner = _physical_owner(boundary, current_ref)
        return ((old_owner is not None and current_owner is not None
                 and old_owner == current_owner == (owner, old_owner[1]))
                or _coherent_materialization(boundary, effect, effects))
    if not path and ref.startswith(("shot-revision:", "internal-revision:")):
        old_owner = _physical_owner(original, ref)
        current_owner = _physical_owner(boundary, ref)
        return old_owner is not None or current_owner is not None or _coherent_materialization(boundary, effect, effects)
    return _coherent_materialization(boundary, effect, effects)


def _align_materialized_images(result, accepted):
    """Map provider-generated physical ids to the accepted authenticated images."""
    for ref, image in list(result.items()):
        if ref == "parent" or not ref.startswith(("shot-revision:", "internal-revision:")):
            continue
        candidates = [candidate for candidate, known in accepted.items()
                      if candidate.startswith(ref.split(":", 1)[0] + ":")
                      and value_equal(known["payload"], image["payload"])
                      and _physical_owner(result, ref) == _physical_owner(accepted, candidate)]
        if len(candidates) != 1:
            continue
        candidate = candidates[0]
        result[candidate] = copy.deepcopy(accepted[candidate])
        if candidate != ref:
            if ref.startswith("shot-revision:"):
                old_id, new_id = ref.partition(":")[2], candidate.partition(":")[2]
                for row in result["parent"]["payload"].get("occurrences", []):
                    if row.get("shot_revision_id") == old_id:
                        row["shot_revision_id"] = new_id
            else:
                old_id, new_id = ref.partition(":")[2], candidate.partition(":")[2]
                for shot_ref, shot in result.items():
                    if shot_ref.startswith("shot-revision:") and shot["payload"].get("internal_timeline_revision_id") == old_id:
                        shot["payload"]["internal_timeline_revision_id"] = new_id
            result.pop(ref)


def _parent_materialization_reconciles(result, accepted):
    """Recognize a landing parent whose only delta is authenticated shot turnover."""
    before = copy.deepcopy(result["parent"]["payload"])
    after = copy.deepcopy(accepted["parent"]["payload"])
    before_rows = {row.get("occurrence_id"): row for row in before.get("occurrences", [])}
    after_rows = {row.get("occurrence_id"): row for row in after.get("occurrences", [])}
    if set(before_rows) != set(after_rows):
        return False
    changed = False
    for occurrence, row in before_rows.items():
        other = after_rows[occurrence]
        old_ref, new_ref = row.get("shot_revision_id"), other.get("shot_revision_id")
        row.pop("shot_revision_id", None)
        other.pop("shot_revision_id", None)
        if old_ref != new_ref:
            changed = True
            if (_physical_owner(result, "shot-revision:" + str(old_ref)) is None
                    or _physical_owner(accepted, "shot-revision:" + str(new_ref)) is None):
                return False
    return changed and value_equal(before, after)


def _reconcile_materialized_owner_images(result, accepted):
    def owner_token(document, ref):
        image = document.get(ref, {})
        if ref.startswith("shot-revision:"):
            return "shot:" + str(image.get("payload", {}).get("internal_timeline_revision_id"))
        if ref.startswith("internal-revision:"):
            return ref
        return None

    owners = {owner_token(accepted, ref) for ref in accepted
              if ref.startswith(("shot-revision:", "internal-revision:"))}
    for owner in owners - {None}:
        result_refs = {ref for ref in result if owner_token(result, ref) == owner}
        accepted_refs = {ref for ref in accepted if owner_token(accepted, ref) == owner}
        for ref in result_refs - accepted_refs:
                result.pop(ref, None)
        for ref in accepted_refs:
            result[ref] = copy.deepcopy(accepted[ref])


def step_output(boundary, step, records, accepted, original=None):
    """Project complete authoritative effects solely to authenticate their boundaries."""
    result = copy.deepcopy(boundary)
    for effect in step["patch"]:
        ref, path = effect["ref"], normalized_path(effect["ref"], effect["path"])
        if ref != "parent" and not path:
            before = {"state": "present", "value": result[ref]["payload"]} if ref in result else {"state": "absent"}
            require(value_equal(before, effect["before"])
                    or _materialization_input(boundary, original, effect, path, step["patch"]),
                    "provider root effect has a different input")
            if effect["op"] == "remove":
                result.pop(ref, None)
            else:
                require(effect["op"] == "set", "provider root effect is not an observed value")
                result[ref] = {**copy.deepcopy(accepted.get(ref, {})), "revision_id": ref.partition(":")[2],
                               "content_digest": digest(effect["value"]), "payload": copy.deepcopy(effect["value"])}
                if ref.startswith("shot-revision:"):
                    result[ref]["internal_timeline_revision_id"] = effect["value"]["internal_timeline_revision_id"]
            continue
        require(ref in result, "provider effect addresses an absent root")
        payload = result[ref]["payload"]
        observed_path = stored_path(payload, ref, path)
        if effect["op"].startswith("list."):
            # List operations are Agent semantics. The recorder supplies the
            # complete resulting collection; Runtime only projects that value.
            observations = [write for ordinal in step["command_ordinals"]
                            for write in records["commands"][ordinal]["writes"]
                            if site(boundary, write["ref"], write["path"]) == (ref, path)]
            require(bool(observations), "provider list effect lacks a full collection observation")
            state = observations[-1]["after"]
        else:
            require(value_equal(location(payload, observed_path), effect["before"])
                    or _materialization_input(boundary, original, effect, observed_path, step["patch"]),
                    "provider effect has a different input value")
            state = {"state": "present", "value": effect["value"]} if effect["op"] == "set" else {"state": "absent"}
        result[ref]["payload"] = project_observation(payload, observed_path, state)
        if ref == "parent" and path[:2] in (["config", "clips"], ["config", "registry"]):
            mirror = path[1]
            if mirror in payload and mirror in result[ref]["payload"].get("config", {}):
                result[ref]["payload"][mirror] = copy.deepcopy(result[ref]["payload"]["config"].get(mirror))
        result[ref]["content_digest"] = digest(result[ref]["payload"])
    _align_materialized_images(result, accepted)
    # Bindings of complete effect images carry the provider's generated revision
    # names. Their payload digest must agree with the projected observations.
    for row in result["parent"]["payload"]["occurrences"]:
        ref = "shot-revision:" + row["shot_revision_id"]
        require(ref in result, "provider occurrence effect has no physical shot image")
        require(result[ref].get("shot_id", row["shot_id"]) == row["shot_id"],
                "provider occurrence effect changes physical shot ownership")
        result[ref]["shot_id"] = row["shot_id"]
    for ref, image in list(result.items()):
        known = accepted.get(ref)
        if ref == "parent":
            pins = [binding for ordinal in step["command_ordinals"]
                    for binding in records["commands"][ordinal]["bindings"]
                    if binding.get("key") == "commit.effect" and binding.get("physical_ref") == ref
                    and binding.get("boundary", {}).get("side") == "after"
                    and binding.get("content_digest") == image["content_digest"]]
            if pins:
                require(len({pin["revision_id"] for pin in pins}) == 1, "provider intermediate parent pins disagree")
                image["revision_id"] = pins[0]["revision_id"]
            else:
                reconciled = known is not None and _parent_materialization_reconciles(result, accepted)
                require(known is not None and (value_equal(known["payload"], image["payload"])
                                                or reconciled),
                        "provider intermediate parent lacks an effect image")
                result[ref] = copy.deepcopy(known)
                if reconciled:
                    _reconcile_materialized_owner_images(result, accepted)
        elif known is not None and value_equal(known["payload"], image["payload"]):
            result[ref] = copy.deepcopy(known)
    return result


def _inverse_stage_write_site(boundary, write):
    """Resolve a staged inverse write, including a root entering the closure."""
    ref, path = write["ref"], write["path"]
    # Native root captures name physical fields. The two parent mirrors can
    # differ between their separately recorded writes within a stage.
    if ref in boundary:
        return ref, path
    if (not path and ref.startswith(("shot-revision:", "internal-revision:"))
            and ref not in boundary):
        return ref, path
    return native_site(boundary, ref, path)


def _inverse_stage_state(boundary, ref, path):
    if ref not in boundary:
        return {"state": "absent"}
    return location(boundary[ref]["payload"], stored_path(boundary[ref]["payload"], ref, path),
                    absent_items=True)


def _inverse_stage_root(boundary, ref):
    """Observe authored aggregate roots through authenticated physical images."""
    kind, _, identity = ref.partition(":")
    if kind == "occurrence":
        state = location(boundary["parent"]["payload"], ["occurrences", "occurrence_id:" + identity],
                         absent_items=True)
        state = copy.deepcopy(state)
        if state["state"] == "present":
            assert isinstance(state["value"], dict)
            state["value"].pop("shot_revision_id", None)
            state["value"].pop("revision_id", None)
        return state, []
    matches = [(key, image) for key, image in boundary.items()
               if key.startswith("shot-revision:") and image.get("shot_id") == identity]
    require(len(matches) <= 1, "inverse stage shot root is ambiguous")
    if not matches:
        return {"state": "absent"}, []
    physical, shot = matches[0]
    internal = "internal-revision:" + shot["internal_timeline_revision_id"]
    require(internal in boundary and shot["payload"].get("internal_timeline_revision_id")
            == shot["internal_timeline_revision_id"], "inverse stage shot root has no authenticated internal image")
    return {"state": "present", "value": {"payload": copy.deepcopy(shot["payload"]),
            "internal_timeline": copy.deepcopy(boundary[internal]["payload"])}}, [physical, internal]


def _inverse_stage_root_equal(observed, claimed, ref):
    if value_equal(observed, claimed):
        return True
    if ref.startswith("shot:") and observed["state"] == "present":
        authored = copy.deepcopy(observed)
        authored["value"]["payload"].pop("internal_timeline_revision_id", None)
        return value_equal(authored, claimed)
    return False


def _inverse_stage_history(records, history):
    """Return the authenticated source stages named by an inverse record."""
    publications = records.get("undo_of")
    require(isinstance(publications, list) and publications and
            all(isinstance(publication, str) and publication for publication in publications)
            and len(set(publications)) == len(publications),
            "inverse stage history targets are malformed")
    require(isinstance(history, dict), "inverse stage history is unavailable")
    require(set(history) == set(publications), "inverse stage history includes non-source publications")
    selected = records.get("undo_steps")
    if selected is not None:
        require(isinstance(selected, dict) and set(selected) == set(publications),
                "inverse stage selection does not cover its history targets")

    expected = []
    for publication in reversed(publications):
        entry = history.get(publication)
        require(isinstance(entry, dict) and entry.get("publication_id") == publication
                and entry.get("intent") == "recorded"
                and isinstance(entry.get("receipt"), dict)
                and entry["receipt"].get("receipt_id") == publication,
                "inverse stage source publication is not authenticated")
        source_records = entry.get("records")
        require(isinstance(source_records, dict)
                and isinstance(source_records.get("commands"), list)
                and isinstance(source_records.get("steps"), list)
                and source_records["commands"],
                "inverse stage source command history is unavailable")
        assert isinstance(source_records, dict)
        commands = source_records["commands"]
        require([record.get("ordinal") for record in commands] == list(range(len(commands))),
                "inverse stage source command ordinals are unavailable")
        source_steps = source_records["steps"]
        assert isinstance(commands, list) and isinstance(source_steps, list)
        step_by_id = {source_step.get("id"): source_step for source_step in source_steps}
        require(len(step_by_id) == len(source_steps) and all(isinstance(identity, str) and identity
                                                            for identity in step_by_id),
                "inverse stage source steps are malformed")
        requested = (list(step_by_id) if selected is None else selected.get(publication))
        require(isinstance(requested, list) and requested and
                all(isinstance(identity, str) and identity in step_by_id for identity in requested)
                and len(set(requested)) == len(requested),
                "inverse stage selected source steps are unavailable")
        for source_step in reversed(source_steps):
            if source_step["id"] not in requested:
                continue
            ordinals = source_step.get("command_ordinals")
            require(isinstance(ordinals, list) and ordinals
                    and ordinals == list(range(ordinals[0], ordinals[0] + len(ordinals)))
                    and all(type(ordinal) is int and 0 <= ordinal < len(commands) for ordinal in ordinals),
                    "inverse stage source step command boundary is malformed")
            source_commands = [commands[ordinal] for ordinal in ordinals]
            native_sites = [(write["ref"], write["path"]) for command in reversed(source_commands)
                            for write in reversed([*command.get("writes", []),
                                *(write for write in command.get("derived_writes", [])
                                  if write.get("ref", "").startswith("parent/clip:")
                                  and write.get("path") in (["at"], ["hold"]))])]
            expected.append({"publication_id": publication, "step_id": source_step["id"],
                             "command_ordinals": ordinals, "native_sites": native_sites})
    return expected


def _inverse_stage_ranges(step, records, history=None):
    """Validate the recorder's stage partition without trusting its images."""
    stages = []
    stage_records = []
    for ordinal in step["command_ordinals"]:
        record = records["commands"][ordinal]
        for binding in record["bindings"]:
            if binding.get("key") == "inverse.stage":
                stages.append(binding)
                stage_records.append(record)
    if not stages:
        return None

    expected = _inverse_stage_history(records, history)
    require(len(stages) == len(expected),
            "inverse stage provenance does not match authenticated history")

    require(all(records["commands"][ordinal]["command"]["op"] == "timeline.inverse"
                for ordinal in step["command_ordinals"]),
            "inverse stage provenance is attached to a non-inverse command")
    final_ordinal = step["command_ordinals"][-1]
    require(all(record["ordinal"] == final_ordinal for record in stage_records),
            "inverse stage provenance is attached to the wrong command")
    record = records["commands"][final_ordinal]
    previous_native_end = 0
    previous_effect_end = 0
    result = []
    for binding, source_stage in zip(stages, expected):
        boundary = binding.get("boundary")
        require(isinstance(boundary, dict), "inverse stage boundary is absent or malformed")
        step_id = boundary.get("step_id")
        command_ordinals = boundary.get("command_ordinals")
        require(binding.get("ref") == "parent" and binding.get("policy") == "fixed"
                and binding.get("dependencies") == []
                and boundary.get("publication_id") == source_stage["publication_id"]
                and step_id == source_stage["step_id"]
                and command_ordinals == source_stage["command_ordinals"],
                "inverse stage provenance differs from authenticated source history")
        require(isinstance(step_id, str) and step_id
                and isinstance(command_ordinals, list) and command_ordinals
                and all(type(item) is int and item >= 0 for item in command_ordinals)
                and len(set(command_ordinals)) == len(command_ordinals)
                and command_ordinals == sorted(command_ordinals),
                "inverse stage command provenance is malformed")
        native_range = boundary.get("native_write_range")
        effect_range = boundary.get("effect_range")
        require(isinstance(native_range, list) and len(native_range) == 2
                and all(type(item) is int for item in native_range),
                "inverse stage native range is malformed")
        require(isinstance(effect_range, list) and len(effect_range) == 2
                and all(type(item) is int for item in effect_range),
                "inverse stage effect range is malformed")
        native_start, native_end = native_range
        effect_start, effect_end = effect_range
        require(native_end - native_start == len(source_stage["native_sites"])
                and native_start == previous_native_end and native_start < native_end <= len(record["writes"]),
                "inverse stage native ranges are missing, reordered, or overlapping")
        require(effect_start == previous_effect_end and effect_start < effect_end <= len(step["patch"]),
                "inverse stage effect ranges are missing, reordered, or overlapping")
        native_sites = [(write["ref"], write["path"]) for write in record["writes"][native_start:native_end]]
        effect_sites = [(effect["ref"], effect["path"]) for effect in step["patch"][effect_start:effect_end]]
        # A recorder may observe the exact canonical stage effects directly or
        # retain the source's finer native captures in reverse execution order.
        # Neither representation permits extra sites or mere ancestor overlap.
        require(native_sites == source_stage["native_sites"] or native_sites == effect_sites,
                "inverse stage native write membership differs from its authenticated stage")
        previous_native_end, previous_effect_end = native_end, effect_end
        result.append({"binding": binding, "record": record, "native_range": native_range,
                       "effect_range": effect_range})
    require(previous_native_end == len(record["writes"])
            and previous_effect_end == len(step["patch"]),
            "inverse stage ranges do not cover the authenticated inverse")
    return result


def _inverse_stage_boundaries(boundary, output, step, records, accepted, original, history=None):
    stages = _inverse_stage_ranges(step, records, history)
    if stages is None:
        return None
    current = boundary
    effect_boundaries = {}
    authenticated_turnovers = []
    effect_bindings = [binding for ordinal in step["command_ordinals"]
                       for binding in records["commands"][ordinal]["bindings"]
                       if binding.get("key") == "commit.effect"]
    for stage in stages:
        effect_start, effect_end = stage["effect_range"]
        stage_before = current
        stage_step = {**step, "patch": step["patch"][effect_start:effect_end]}
        stage_after = step_output(stage_before, stage_step, records, accepted, original=stage_before)
        native_start, native_end = stage["native_range"]
        writes = stage["record"]["writes"][native_start:native_end]
        source_boundary = stage["binding"].get("boundary", {})
        source_entry = (history or {}).get(source_boundary.get("publication_id"), {})
        source_records = source_entry.get("records", {})
        source_commands = source_records.get("commands", [])
        source_steps = source_records.get("steps", [])
        source_step = next((item for item in source_steps
                            if item.get("id") == source_boundary.get("step_id")), None)
        source_bindings = []
        if source_step is not None:
            source_bindings = [binding for ordinal in source_step.get("command_ordinals", [])
                               if isinstance(ordinal, int) and ordinal < len(source_commands)
                               for binding in source_commands[ordinal].get("bindings", [])
                               if binding.get("key") == "commit.materialization"]
        native_image = copy.deepcopy(stage_before)
        root_checks = []
        # Native captures observe each preceding write (including empty ancestor
        # removals); canonical effects describe the complete stage transition.
        for write in writes:
            if not write["path"] and re.fullmatch(r"(?:shot|occurrence):[^/]+", write["ref"]):
                root = write["ref"]
                observed, physical = _inverse_stage_root(native_image, root)
                after, successors = _inverse_stage_root(stage_after, root)
                root_checks.append((observed, write["before"], root, physical,
                                    after, write["after"], successors))
                if root.startswith("occurrence:"):
                    path = ["occurrences", "occurrence_id:" + root.partition(":")[2]]
                    state = location(stage_after["parent"]["payload"], path, absent_items=True)
                    native_image["parent"]["payload"] = project_observation(
                        native_image["parent"]["payload"], path, state)
                else:
                    for ref in physical:
                        if ref.startswith("internal-revision:") and any(
                                image.get("internal_timeline_revision_id") == ref.partition(":")[2]
                                for key, image in native_image.items()
                                if key.startswith("shot-revision:") and key not in physical):
                            continue
                        native_image.pop(ref)
                    for ref in successors:
                        native_image[ref] = copy.deepcopy(stage_after[ref])
                continue
            ref, path = _inverse_stage_write_site(native_image, write)
            require(value_equal(_inverse_stage_state(native_image, ref, path), write["before"]),
                    "inverse stage write differs from its sequential input")
            if not path and ref not in native_image:
                require(ref in stage_after and value_equal(
                    {"state": "present", "value": stage_after[ref]["payload"]}, write["after"]),
                    "inverse stage root differs from its authenticated effect image")
                native_image[ref] = copy.deepcopy(stage_after[ref])
            elif not path and write["after"]["state"] == "absent":
                native_image.pop(ref)
            else:
                payload = native_image[ref]["payload"]
                observed_path = stored_path(payload, ref, path)
                native_image[ref]["payload"] = project_observation(payload, observed_path, write["after"])
                if (write["ref"].startswith("occurrence:") and "/" not in write["ref"]
                        and write["path"] == ["shot_id"] and source_step is not None):
                    fork_commands = [source_commands[ordinal]
                                     for ordinal in source_step["command_ordinals"]
                                     if source_commands[ordinal]["command"]["op"] == "occurrence.fork"]
                    captures = [capture for command in fork_commands for capture in command["writes"]
                                if capture["ref"] == write["ref"] and capture["path"] == write["path"]]
                    if captures:
                        require(len(captures) == 1 and value_equal(captures[0]["after"], write["before"])
                                and value_equal(captures[0]["before"], write["after"]),
                                "inverse fork differs from its authenticated native capture")
                        occurrence_path = ["occurrences", "occurrence_id:" + write["ref"].partition(":")[2]]
                        # The native fork's source alias can predate the physical
                        # source pin. Restore that exact accepted source pair.
                        for field in ("shot_id", "shot_revision_id"):
                            effects = [effect for effect in source_step["patch"]
                                       if effect["ref"] == "parent" and effect["path"] == [*occurrence_path, field]]
                            require(len(effects) == 1 and effects[0]["op"] == "set"
                                    and value_equal(location(stage_before["parent"]["payload"],
                                                             [*occurrence_path, field]),
                                                    {"state": "present", "value": effects[0]["value"]}),
                                    "inverse fork differs from its authenticated source edge")
                            native_image["parent"]["payload"] = project_observation(
                                native_image["parent"]["payload"], [*occurrence_path, field], effects[0]["before"])
                if ref == "parent" and write["ref"].startswith(("parent/clip:", "parent/asset:")):
                    projected = native_image[ref]["payload"]
                    for mirror in (("clips",) if write["ref"].startswith("parent/clip:") else ("registry",)):
                        if mirror in projected and mirror in projected.get("config", {}):
                            projected[mirror] = copy.deepcopy(projected["config"][mirror])
        # A leaf native write can restore authored bytes while the accepted
        # source records an authenticated physical turnover.  In that case,
        # reverse the source materialization edges; never infer a new root or
        # copy an arbitrary stage image.
        transitions = []
        for binding in source_bindings:
            assert source_step is not None
            source_new = binding.get("physical_ref")
            source_old = binding.get("successor")
            owner = binding.get("owner")
            attribution = binding.get("boundary", {})
            require(binding.get("ref") == source_new
                    and binding.get("step_id") == source_step["id"]
                    and attribution.get("step_id") == source_step["id"]
                    and attribution.get("command_ordinal") in source_step["command_ordinals"]
                    and attribution.get("phase") == "input"
                    and attribution.get("base_revision_id") == source_entry["receipt"]["result"]["base_revision_id"]
                    and attribution.get("base_publication_id") == source_entry["receipt"]["result"]["base_publication_id"]
                    and value_equal(attribution.get("evaluated_head"), source_entry["previous"]),
                    "inverse stage source materialization attribution differs from history")
            require(binding.get("policy") == "fixed"
                    and binding.get("dependencies") == []
                    and isinstance(source_new, str) and isinstance(source_old, str)
                    and source_new.startswith(("shot-revision:", "internal-revision:"))
                    and source_old.startswith(("shot-revision:", "internal-revision:")),
                    "inverse stage source materialization is malformed")
            old, new = source_old, source_new
            require(old != new and old in stage_before and new in stage_after
                    and old not in stage_after and new not in stage_before,
                    "inverse stage source materialization is outside its physical turnover")
            require(isinstance(owner, str) and owner.startswith("occurrence:")
                    and owner.endswith("/shot") and binding.get("owners") == [owner],
                    "inverse stage source materialization owner is malformed")
            occurrence = owner.removeprefix("occurrence:").removesuffix("/shot")
            before_rows = [row for row in stage_before["parent"]["payload"].get("occurrences", [])
                           if row.get("occurrence_id") == occurrence]
            after_rows = [row for row in stage_after["parent"]["payload"].get("occurrences", [])
                          if row.get("occurrence_id") == occurrence]
            require(len(before_rows) == len(after_rows) == 1,
                    "inverse stage materialization owner is absent or ambiguous")
            before_row, after_row = before_rows[0], after_rows[0]
            require(before_row["shot_id"] == after_row["shot_id"]
                    and _physical_owner(stage_before, old) == (occurrence, before_row["shot_id"])
                    and _physical_owner(stage_after, new) == (occurrence, after_row["shot_id"]),
                    "inverse stage materialization changes physical ownership")
            before_shot = "shot-revision:" + str(before_row["shot_revision_id"])
            after_shot = "shot-revision:" + str(after_row["shot_revision_id"])
            before_internal = "internal-revision:" + str(stage_before[before_shot]["internal_timeline_revision_id"])
            after_internal = "internal-revision:" + str(stage_after[after_shot]["internal_timeline_revision_id"])
            if old == before_shot and new == after_shot:
                expected_edges = (before_internal, after_internal)
            elif old == before_internal and new == after_internal:
                expected_edges = (before_shot, after_shot)
            else:
                require(False, "inverse stage materialization differs from its owner edges")
                expected_edges = (None, None)
            require(binding.get("edge_before") == expected_edges[1]
                    and binding.get("edge_after") == expected_edges[0]
                    and binding.get("revision_id") == stage_after[new]["revision_id"]
                    and binding.get("content_digest") == stage_after[new]["content_digest"],
                    "inverse stage source materialization differs from its successor image")
            source_images = [pin for ordinal in source_step["command_ordinals"]
                             for pin in source_commands[ordinal]["bindings"]
                             if pin.get("key") == "commit.effect" and pin.get("physical_ref") == new
                             and pin.get("boundary", {}).get("side") == "before"]
            require(source_images and all(pin.get("revision_id") == binding["revision_id"]
                                          and pin.get("content_digest") == binding["content_digest"]
                                          for pin in source_images),
                    "inverse stage materialization differs from its recorded source image")
            sibling = [item for item in source_bindings
                       if item.get("physical_ref") == binding.get("edge_before")
                       and item.get("successor") == binding.get("edge_after")]
            require(len(sibling) == 1 and sibling[0].get("owner") == owner
                    and sibling[0].get("owners") == [owner]
                    and sibling[0].get("edge_before") == source_new
                    and sibling[0].get("edge_after") == source_old,
                    "inverse stage source materialization has no authenticated sibling edge")
            require((old, new) not in [(item[0], item[1]) for item in transitions],
                    "inverse stage materialization has an ambiguous successor")
            transitions.append((old, new, before_internal, after_internal,
                                before_shot, after_shot))

        shot_turnovers = {(old, new): (before_internal, after_internal)
                          for old, new, before_internal, after_internal, _, _ in transitions
                          if old.startswith("shot-revision:")}
        for old, new, before_internal, after_internal, before_shot, after_shot in transitions:
            image = native_image.pop(old)
            expected = stage_after[new]
            if old.startswith("internal-revision:"):
                require(value_equal(image["payload"], expected["payload"]),
                        "inverse stage materialization changes internal payload")
            else:
                payload = copy.deepcopy(image["payload"])
                require(payload.get("internal_timeline_revision_id") == before_internal.partition(":")[2],
                        "inverse stage materialization has a wrong shot pin")
                payload["internal_timeline_revision_id"] = after_internal.partition(":")[2]
                require(value_equal(payload, expected["payload"]),
                        "inverse stage materialization changes shot payload")
                image["payload"] = payload
                image["internal_timeline_revision_id"] = after_internal.partition(":")[2]
            require(image.get("shot_id") == expected.get("shot_id"),
                    "inverse stage materialization changes physical ownership")
            image["revision_id"] = expected["revision_id"]
            image["content_digest"] = expected["content_digest"]
            require(image["content_digest"] == digest(image["payload"]),
                    "inverse stage materialization has an unauthenticated payload digest")
            native_image[new] = image
        for row in native_image["parent"]["payload"].get("occurrences", []):
            for old, new in shot_turnovers:
                if row.get("shot_revision_id") == old.partition(":")[2]:
                    row["shot_revision_id"] = new.partition(":")[2]
        for observed, before_claim, root, physical, after, after_claim, successors in root_checks:
            before_claim = copy.deepcopy(before_claim)
            after_claim = copy.deepcopy(after_claim)
            # A later aggregate capture retains the pin from the native source
            # execution. Translate only the exact edge already proved in an
            # earlier inverse stage, preserving every other aggregate byte.
            for claim, refs in ((before_claim, physical), (after_claim, successors)):
                if root.startswith("shot:") and claim["state"] == "present":
                    payload = claim["value"]["payload"]
                    for old, new, old_internal, new_internal, _, _ in authenticated_turnovers:
                        if (new in refs and old.startswith("shot-revision:")
                                and payload.get("internal_timeline_revision_id") == old_internal.partition(":")[2]):
                            payload["internal_timeline_revision_id"] = new_internal.partition(":")[2]
            require(_inverse_stage_root_equal(observed, before_claim, root),
                    "inverse stage root differs from its sequential input")
            require(_inverse_stage_root_equal(after, after_claim, root),
                    "inverse stage root differs from its authenticated effect image")
        authenticated_turnovers.extend(transitions)

        require(value_equal({ref: image["payload"] for ref, image in native_image.items()},
                            {ref: image["payload"] for ref, image in stage_after.items()}),
                "inverse stage native writes do not cover its authenticated effect image")
        for write in writes:
            if not write["path"] and re.fullmatch(r"(?:shot|occurrence):[^/]+", write["ref"]):
                require(value_equal(_inverse_stage_root(native_image, write["ref"])[0],
                                    _inverse_stage_root(stage_after, write["ref"])[0]),
                        "inverse stage roots differ from its authenticated effect image")
                continue
            before_ref, before_path = _inverse_stage_write_site(native_image, write)
            after_ref, after_path = _inverse_stage_write_site(stage_after, write)
            require(before_ref == after_ref and before_path == after_path
                    and value_equal(_inverse_stage_state(native_image, before_ref, before_path),
                                    _inverse_stage_state(stage_after, after_ref, after_path)),
                    "inverse stage writes differ from its authenticated effect image")
        for index in range(effect_start, effect_end):
            effect = step["patch"][index]
            for side, image in (("before", stage_before), ("after", stage_after)):
                if (effect["ref"] in image or (not effect["path"]
                        and effect["ref"].startswith(("shot-revision:", "internal-revision:")))):
                    physical = effect["ref"]
                else:
                    physical, _ = site(image, effect["ref"], effect["path"])
                expected = [binding for binding in effect_bindings
                            if binding.get("effect_ordinal") == index
                            and binding.get("boundary", {}).get("side") == side
                            and binding.get("physical_ref") == physical]
                if physical in image:
                    require(len(expected) == 1,
                            "provider inverse effect bindings do not cover its stage image")
            effect_boundaries[index] = (stage_before, stage_after)
        current = stage_after
    require(value_equal(current, output), "inverse stage images do not reach the authenticated output")
    return effect_boundaries


def _authoring_parent_identity(boundary, identity_scope, manifest):
    """Derive the parent pin from sequential images and retained input pins."""
    project_id, timeline_id = identity_scope
    manifest = copy.deepcopy(manifest or {"media": [], "documents": []})
    for family, prefix, keys, order in (
            ("shots", "shot-revision:", ("shot_id", "revision_id", "internal_timeline_revision_id", "content_digest"),
             ("shot_id", "revision_id")),
            ("internal_timelines", "internal-revision:", ("timeline_id", "revision_id", "content_digest"),
             ("timeline_id", "revision_id"))):
        manifest[family] = sorted(({key: image[key] for key in keys} for ref, image in boundary.items()
                                   if ref.startswith(prefix)), key=lambda row: tuple(row[key] for key in order))
    return "authoring-parent-revision-" + digest({
        "project_id": project_id, "timeline_id": timeline_id,
        "parent": boundary["parent"]["payload"], "manifest": manifest,
    }).removeprefix("sha256:")


def _project_created_child(boundary, record, following, accepted, identity_scope=None):
    """Carry an authenticated occurrence birth into the next command input.

    Native occurrence creation records authored aggregate roots, while the
    Runtime closure stores their physical shot/internal images.  A later
    command in the same step must see the birth, but must not inherit the
    later command's final payload. Build the intermediate view and scoped
    allocation identities from creation writes; check the accepted owner
    edges without borrowing their later payloads.
    """
    created = {item.get("ref"): item for item in record.get("created", [])}
    projected_roots = set()
    future_refs = [read.get("ref") for read in following.get("reads", [])]
    future_refs.extend(binding.get("ref") for binding in following.get("bindings", []))
    future_refs.extend(write.get("ref") for write in following.get("writes", []))

    for occurrence_ref, allocation in created.items():
        if not (isinstance(occurrence_ref, str) and occurrence_ref.startswith("occurrence:")
                and "/" not in occurrence_ref
                and any(ref == occurrence_ref or isinstance(ref, str) and ref.startswith(occurrence_ref + "/")
                        for ref in future_refs)):
            continue
        occurrence_write = next((write for write in record.get("writes", [])
                                 if write.get("ref") == occurrence_ref and not write.get("path")), None)
        occurrence_value = ((occurrence_write or {}).get("after", {}).get("value"))
        shot_id = occurrence_value.get("shot_id") if isinstance(occurrence_value, dict) else None
        if (allocation.get("kind") != "occurrence" or allocation.get("owner") != "parent"
                or not isinstance(shot_id, str)):
            require(False, "provider created occurrence root is not an authenticated parent birth")
            continue
        require(occurrence_write is not None
                and occurrence_write.get("before") == {"state": "absent"}
                and occurrence_write.get("after", {}).get("state") == "present",
                "provider created occurrence lacks its absent-to-present root write")

        accepted_shot_refs = [ref for ref, image in accepted.items()
                              if ref.startswith("shot-revision:") and image.get("shot_id") == shot_id]
        require(len(accepted_shot_refs) == 1,
                "provider created occurrence has an ambiguous accepted physical shot")
        if len(accepted_shot_refs) != 1:
            require(False, "provider created occurrence has no accepted physical shot")
            continue
        accepted_shot_ref = accepted_shot_refs[0]
        accepted_shot = accepted[accepted_shot_ref]
        accepted_internal_id = accepted_shot.get("internal_timeline_revision_id")
        if not isinstance(accepted_internal_id, str):
            require(False, "provider created occurrence has no accepted physical internal timeline")
            continue
        accepted_internal_ref = "internal-revision:" + str(accepted_internal_id)
        if accepted_internal_ref not in accepted:
            require(False, "provider created occurrence has no accepted physical internal timeline")
            continue
        accepted_internal = accepted[accepted_internal_ref]

        shot_write = next((write for write in record.get("writes", [])
                           if write.get("ref") == "shot:" + shot_id and not write.get("path")), None)
        if not isinstance(shot_write, dict):
            require(False, "provider created occurrence lacks its authored shot birth")
            continue
        require(shot_write.get("before") == {"state": "absent"}
                and shot_write.get("after", {}).get("state") == "present",
                "provider created occurrence lacks its authored shot birth")
        shot_value = shot_write["after"]["value"]
        require(isinstance(shot_value, dict)
                and isinstance(shot_value.get("payload"), dict)
                and isinstance(shot_value.get("internal_timeline"), dict),
                "provider created shot birth is malformed")
        if (not isinstance(shot_value, dict)
                or not isinstance(shot_value.get("payload"), dict)
                or not isinstance(shot_value.get("internal_timeline"), dict)):
            continue
        initial_shot = copy.deepcopy(shot_value["payload"])
        authored_shot = copy.deepcopy(initial_shot)
        initial_internal = copy.deepcopy(shot_value["internal_timeline"])
        if identity_scope is None:
            shot_ref = accepted_shot_ref
            internal_ref = accepted_internal_ref
            internal_id = accepted_internal_id
            shot_revision_id = shot_ref.partition(":")[2]
        else:
            project_id, timeline_id = identity_scope
            require(accepted_internal.get("timeline_id") == timeline_id,
                    "provider created occurrence internal timeline has a foreign owner")
            internal_id = _authoring_identity("authoring-timeline-revision", project_id, timeline_id,
                                              shot_id, initial_internal)
            initial_shot["internal_timeline_revision_id"] = internal_id
            shot_revision_id = _authoring_identity("authoring-shot-revision", project_id, shot_id,
                                                   initial_shot)
            shot_ref = "shot-revision:" + shot_revision_id
            internal_ref = "internal-revision:" + internal_id
        internal_image = copy.deepcopy(accepted_internal)

        # Every physical alias claimed by the next command must still belong
        # to this exact created occurrence. A source pin cannot retarget the
        # child to a foreign or future physical image.
        for binding in following.get("bindings", []):
            ref = binding.get("ref")
            if not (isinstance(ref, str) and (ref == occurrence_ref or ref.startswith(occurrence_ref + "/"))):
                continue
            physical = binding.get("physical_ref")
            if physical is None:
                continue
            require(physical in {"parent", shot_ref, internal_ref},
                    "provider created occurrence source pin is foreign")
            if ref == occurrence_ref + "/source":
                require(physical == internal_ref,
                        "provider created occurrence source pin differs from its child")

        accepted_occurrences = accepted["parent"]["payload"].get("occurrences", [])
        accepted_occurrence = [row for row in accepted_occurrences
                               if row.get("occurrence_id") == occurrence_ref.partition(":")[2]]
        require(len(accepted_occurrence) == 1
                and accepted_occurrence[0].get("shot_id") == shot_id
                and accepted_occurrence[0].get("shot_revision_id") == accepted_shot_ref.partition(":")[2],
                "provider created occurrence has an ambiguous accepted owner")
        # Keep authored creation fields from the earlier native write; only the
        # managed shot revision edge comes from the accepted physical closure.
        intermediate_occurrence = copy.deepcopy(occurrence_value)
        intermediate_occurrence["shot_revision_id"] = shot_revision_id
        if identity_scope is not None:
            accepted_payload = accepted_shot.get("payload")
            require(isinstance(accepted_payload, dict)
                    and {key: value for key, value in accepted_payload.items()
                         if key != "internal_timeline_revision_id"} == authored_shot,
                    "provider created occurrence accepted shot is not its authored allocation")
            projected_parent = copy.deepcopy(boundary["parent"]["payload"])
            projected_parent.setdefault("occurrences", []).append(intermediate_occurrence)
            parent_pins = [binding for binding in following.get("bindings", [])
                           if binding.get("physical_ref") == "parent"
                           and binding.get("boundary", {}).get("phase") == "input"
                           and binding.get("content_digest") == digest(projected_parent)]
            require(parent_pins,
                    "provider created occurrence lacks an authenticated authoring allocation mapping")
        require(all(accepted_occurrence[0].get(key) == value
                    for key, value in occurrence_value.items()),
                "provider created occurrence differs from its accepted owner")

        result_parent = boundary["parent"]
        payload = copy.deepcopy(result_parent["payload"])
        occurrences = payload.setdefault("occurrences", [])
        require(not any(row.get("occurrence_id") == intermediate_occurrence["occurrence_id"]
                        for row in occurrences),
                "provider created occurrence is already present at its input boundary")
        occurrences.append(intermediate_occurrence)
        result_parent["payload"] = payload
        result_parent["content_digest"] = digest(payload)

        require(shot_ref not in boundary and internal_ref not in boundary,
                "provider created occurrence physical roots overlap its input boundary")
        result_shot = copy.deepcopy(accepted_shot)
        result_shot["revision_id"] = shot_revision_id
        result_shot["internal_timeline_revision_id"] = internal_id
        result_shot["payload"] = initial_shot
        result_shot["content_digest"] = digest(initial_shot)
        result_internal = copy.deepcopy(internal_image)
        result_internal["revision_id"] = internal_id
        result_internal["payload"] = initial_internal
        result_internal["content_digest"] = digest(initial_internal)
        for binding in following.get("bindings", []):
            if binding.get("ref") == occurrence_ref + "/source":
                require(binding.get("content_digest") == result_internal["content_digest"],
                        "provider created occurrence source digest differs from its birth")
        boundary[shot_ref] = result_shot
        boundary[internal_ref] = result_internal
        projected_roots.update({"shot:" + shot_id, occurrence_ref})
    return projected_roots


def _following_read_observes(boundary, following, physical_ref):
    for read in following.get("reads", []):
        ref, path = native_site(boundary, read["ref"], read["path"])
        if ref != physical_ref:
            continue
        if not path and "/collection:" in read["ref"]:
            return True
        if not path:
            continue
        observed = location(boundary[ref]["payload"], stored_path(boundary[ref]["payload"], ref, path))
        if value_equal(observed, read.get("state")):
            return True
    return False


def command_output(boundary, record, following, *, accepted=None, identity_scope=None, manifest=None):
    """Project full recorder observations needed by a subsequent input binding."""
    result = copy.deepcopy(boundary)
    projected_roots = (_project_created_child(result, record, following, accepted, identity_scope)
                       if accepted is not None else set())
    created_roots = {item.get("ref") for item in record.get("created", [])
                     if re.fullmatch(r"(?:shot|occurrence):[^/]+", item.get("ref", ""))}
    for capture in [*record["writes"], *record["derived_writes"]]:
        if capture.get("ref") in created_roots & projected_roots and not capture.get("path"):
            # The authored aggregate root was installed above through its
            # physical closure images; it has no direct Runtime image site.
            continue
        ref, path = native_site(result, capture["ref"], capture["path"])
        require(ref in result, "provider intermediate command lacks an authenticated physical observation")
        payload = result[ref]["payload"]
        path = stored_path(payload, ref, path)
        before_payload = boundary.get(ref, result[ref])["payload"] if "cause" in capture else payload
        require(value_equal(location(before_payload, path, absent_items=True), capture["before"]),
                "provider intermediate command has a different input observation")
        result[ref]["payload"] = project_observation(payload, path, capture["after"])
        if ref == "parent":
            for mirror in ("clips", "registry"):
                projected = result[ref]["payload"]
                if mirror in projected and mirror in projected.get("config", {}):
                    projected[mirror] = copy.deepcopy(projected["config"][mirror])
        result[ref]["content_digest"] = digest(result[ref]["payload"])
    for ref, image in list(result.items()):
        if ref not in boundary:
            continue
        if image["content_digest"] == boundary[ref]["content_digest"]:
            continue
        pins = [binding for binding in following["bindings"] if binding.get("physical_ref") == ref
                and binding.get("boundary", {}).get("phase") == "input"
                and binding.get("content_digest") == image["content_digest"]]
        if pins:
            require(len({pin["revision_id"] for pin in pins}) == 1,
                    "provider intermediate image differs from recorded command observations")
            require(ref == "parent",
                    "provider intermediate changed payload retains its immutable physical identity")
            image["revision_id"] = pins[0]["revision_id"]
        else:
            aliases = [binding for binding in following["bindings"]
                       if isinstance(binding.get("physical_ref"), str)
                       and binding["physical_ref"].startswith(("shot-revision:", "internal-revision:"))
                       and binding.get("physical_ref") != ref
                       and binding.get("boundary", {}).get("phase") == "input"
                       and binding.get("content_digest") == image["content_digest"]]
            if aliases:
                require(len({binding["physical_ref"] for binding in aliases}) == 1,
                        "provider intermediate image has ambiguous authenticated promotion")
                alias = aliases[0]
                target = alias["physical_ref"]
                require(target.split(":", 1)[0] == ref.split(":", 1)[0]
                        and alias["revision_id"] == target.partition(":")[2],
                        "provider intermediate promotion changes its physical kind or identity")
                require(target not in result,
                        "provider intermediate image promotion overlaps an authenticated root")
                if identity_scope is None:
                    require(False, "provider intermediate promotion lacks an authenticated allocation")
                    continue
                project_id, timeline_id = identity_scope
                target_id = target.partition(":")[2]
                source_id = ref.partition(":")[2]
                if ref.startswith("internal-revision:"):
                    owners = [(owner_ref, owner) for owner_ref, owner in result.items()
                              if owner_ref.startswith("shot-revision:")
                              and owner.get("internal_timeline_revision_id") == source_id]
                    require(len(owners) == 1,
                            "provider intermediate image has an ambiguous physical owner")
                    old_shot_ref, owner = owners[0]
                    shot_id = owner["shot_id"]
                    require(target_id == _authoring_identity(
                        "authoring-timeline-revision", project_id, timeline_id, owner["shot_id"], image["payload"]),
                        "provider intermediate promotion differs from its sequential allocation")
                    payload = owner["payload"]
                    require(payload.get("internal_timeline_revision_id") == source_id,
                            "provider intermediate image owner has a different physical edge")
                    owner["internal_timeline_revision_id"] = target_id
                    payload["internal_timeline_revision_id"] = target_id
                    owner["content_digest"] = digest(payload)
                    successor_shot_id = _authoring_identity(
                        "authoring-shot-revision", project_id, owner["shot_id"], payload)
                    successor_shot_ref = "shot-revision:" + successor_shot_id
                    require(successor_shot_ref not in result,
                            "provider intermediate shot promotion overlaps an authenticated root")
                    owner["revision_id"] = successor_shot_id
                    result[successor_shot_ref] = result.pop(old_shot_ref)
                else:
                    shot_id = image["shot_id"]
                    require(target_id == _authoring_identity(
                        "authoring-shot-revision", project_id, image["shot_id"], image["payload"]),
                        "provider intermediate shot promotion differs from its sequential allocation")
                    old_shot_ref, successor_shot_id = ref, target_id
                parent = result["parent"]["payload"]
                owners = [row for row in parent.get("occurrences", [])
                          if row.get("shot_revision_id") == old_shot_ref.partition(":")[2]]
                require(owners and all(row.get("shot_id") == shot_id for row in owners),
                        "provider intermediate promotion lacks its authenticated parent owner")
                for row in owners:
                    row["shot_revision_id"] = successor_shot_id
                result["parent"]["content_digest"] = digest(parent)
                image["revision_id"] = target_id
                result[target] = result.pop(ref)
                expected_parent = _authoring_parent_identity(result, identity_scope, manifest)
                parent_pins = [binding for binding in following["bindings"]
                               if binding.get("physical_ref") == "parent"
                               and binding.get("boundary", {}).get("phase") == "input"]
                require(parent_pins and all(pin.get("revision_id") == expected_parent
                                           and pin.get("content_digest") == result["parent"]["content_digest"]
                                           for pin in parent_pins),
                        "provider intermediate parent promotion differs from its sequential allocation")
                result["parent"]["revision_id"] = expected_parent
            else:
                require(not ref.startswith(("shot-revision:", "internal-revision:")),
                        "provider intermediate image lacks an authenticated physical promotion")
                require(_following_read_observes(result, following, ref),
                        "provider intermediate image lacks a next-command authenticated read")
    if projected_roots and identity_scope is not None:
        expected_parent = _authoring_parent_identity(result, identity_scope, manifest)
        parent_pins = [binding for binding in following["bindings"]
                       if binding.get("physical_ref") == "parent"
                       and binding.get("boundary", {}).get("phase") == "input"]
        require(parent_pins and all(pin.get("revision_id") == expected_parent
                                   and pin.get("content_digest") == result["parent"]["content_digest"]
                                   for pin in parent_pins),
                "provider created parent differs from its sequential allocation")
        result["parent"]["revision_id"] = expected_parent
    return result


def validate(request, prepared, source, base=None, continuations=None, history=None):
    """Check request/record correspondence at authenticated immutable boundaries."""
    records = prepared["records"]
    continuations = copy.deepcopy(continuations or {})
    boundary = images(source)
    original = images(base or source)
    if base is not None:
        for read in request.get("reads", []):
            validate_read(images(base), read)
    batch_reads = [validate_read(boundary, read, continuations) for read in request.get("reads", [])]
    validate_claims(request, records)
    accepted = images(prepared["canonical_document"])
    touched = set()
    manifest = copy.deepcopy(source["dependency_manifest"])
    if records["merge_mode"] == "atomic":
        for record in records["commands"]:
            for capture in [*record["writes"], *record["reads"], *record["derived_writes"]]:
                touched.add(native_site(boundary, capture["ref"], capture["path"])[0])
            touched.update(binding["physical_ref"] for binding in record["bindings"] if "physical_ref" in binding)
    for step in records["steps"]:
        command_inputs = {step["command_ordinals"][0]: boundary}
        input_manifest = copy.deepcopy(manifest)
        command_manifests = {}
        for ordinal in step["command_ordinals"]:
            # Consumed input pins are checked by the request-private port at
            # acceptance. Only earlier commands contribute to this boundary;
            # a following binding cannot allocate a physical identity.
            for dependency in records["commands"][ordinal]["dependencies"]:
                pin = dependency.get("pin", {})
                if dependency.get("kind") == "media":
                    media_id = pin.get("object_id", pin.get("media_id"))
                    if media_id is not None:
                        media = {row["media_id"]: row for row in manifest["media"]}
                        media[media_id] = {"media_id": media_id, "content_digest": media_id}
                        manifest["media"] = sorted(media.values(), key=lambda row: row["media_id"])
                elif dependency.get("kind") in {"source", "transcript"} and pin not in manifest["documents"]:
                    manifest["documents"].append(copy.deepcopy(pin))
                    manifest["documents"].sort(key=lambda row: (row["document_id"], row["version"], row["content_digest"]))
            command_manifests[ordinal] = copy.deepcopy(manifest)
        # Hydrated documents consumed by the first command can rekey the
        # unchanged effect-before parent. Later commands cannot allocate it.
        input_manifest["documents"] = command_manifests[step["command_ordinals"][0]]["documents"]
        input_parent_revision = None
        if input_manifest["documents"] != source["dependency_manifest"]["documents"]:
            input_parent_revision = _authoring_parent_identity(
                boundary, (source["project_id"], source["timeline_id"]), input_manifest)
        for ordinal, next_ordinal in zip(step["command_ordinals"], step["command_ordinals"][1:]):
            command_inputs[next_ordinal] = command_output(
                command_inputs[ordinal], records["commands"][ordinal], records["commands"][next_ordinal],
                accepted=accepted, identity_scope=(source["project_id"], source["timeline_id"]),
                manifest=command_manifests[ordinal])
        validate_step(request, records, step, boundary, batch_reads, continuations, command_inputs)
        for ref in touched:
            require(covers(step["dependencies"], {"kind": "scope", "ref": ref, "path": []}),
                    "provider atomic dependency union omits a touched scope")
        output = step_output(boundary, step, records, accepted, original)
        effect_boundaries = _inverse_stage_boundaries(boundary, output, step, records, accepted, original, history)
        for ordinal in step["command_ordinals"]:
            record = records["commands"][ordinal]
            command_input = command_inputs[ordinal]
            if record["command"]["op"] == "doc.patch":
                indices = [binding.get("boundary", {}).get("change_ordinal") for binding in record["bindings"]
                           if binding["key"].startswith("doc.patch:")]
                require(indices == list(range(len(record["command"]["args"]["changes"]))),
                        "provider patch bindings do not cover its ordered changes")
            validate_bindings(request, records, prepared["expected_head"], command_input, output, step, ordinal,
                              continuations, original, boundary, effect_boundaries, input_parent_revision)
        for ordinal in step["command_ordinals"]:
            for binding in records["commands"][ordinal]["bindings"]:
                if binding.get("key") == "commit.materialization":
                    continuations.setdefault(binding["physical_ref"], set()).add(binding["successor"])
        boundary = output
    # Materialization can reuse a historical parent revision with these exact
    # bytes. Step bindings still name the projected execution image above;
    # immutable destination provenance is checked separately by the store.
    boundary["parent"]["revision_id"] = accepted["parent"]["revision_id"]
    require(value_equal(boundary, accepted), "provider step effects do not reach the accepted closure")

"""Renderer-free persistence for the frozen timeline commit contract.

Callers supply schema/event validation and request-private input captures. Only
this module owns the acceptance transaction; provider execution belongs outside
RealmStore's mutex.
"""
from __future__ import annotations

import base64
import hashlib
import json
import re

from .errors import ConflictError, ProtocolError, ValidationError
from .idempotency import command_result
from .timeline_commit_validation import detached, digest
from .timeline_materialization import has_materialization, item_identity, materialization_join, root_identity
from .util import canonical_json, new_id, now

_METADATA = ("source", "label", "rationale", "group_id")
_DIGEST = re.compile(r"sha256:[0-9a-f]{64}\Z")
_TEXT_BINDING_REF = re.compile(r"occurrence:([^/]+)/text-binding:(prompt|voiceover_script|transcript)(?::([a-z][a-z0-9-]{0,63}))?\Z")


def reject(reason, message=None, *, status=409):
    from .timeline_commit import CommitRejected

    raise CommitRejected({"http_status": status, "code": "conflict" if status == 409 else "validation_error",
                          "message": message or reason, "details": {"status": "refused", "reason": reason,
                          "base": None, "current": None, "conflicts": []}})


def request_identity(context):
    invocation = context["invocation"]
    return hashlib.sha256(canonical_json({"operation": invocation["operation"], "path": invocation["path"],
                          "publisher": context["publisher"], "request": invocation["body"]}).encode()).hexdigest()


def scope(context):
    request = context["request"]
    return canonical_json([request["project_id"], request["timeline_id"]])


def _effective_merge_mode(request):
    """Return the contract's requested mode after the conservative patch rule."""
    requested = request.get("merge", "fields")
    if requested == "atomic":
        return "atomic"

    def contains_document_patch(commands):
        for command in commands:
            if command.get("op") == "doc.patch":
                return True
            if command.get("op") == "timeline.batch" and contains_document_patch(command.get("args", {}).get("commands", [])):
                return True
        return False

    if "reads" not in request and contains_document_patch(request.get("commands", [])):
        return "atomic"
    return requested


def _is_v2_request(request, records=None):
    """Return whether the caller opted into the v2 request annotations.

    ABI-1 requests are intentionally left byte-for-byte compatible: their
    result and legacy history metadata must not acquire synthetic v2 fields.
    Once any v2 control is present, the provider's authoritative step records
    and the effective merge mode are part of the durable result.
    """
    return any(key in request for key in ("label", "steps", "merge", "reads")) or (
        records is not None and "steps" in records
    ) or any(command.get("op") == "doc.patch" for command in request.get("commands", []))


def _history_metadata(request, data):
    """Project request annotations and effective commit facts into one JSON value.

    The value is stored in the existing history row.  In particular, no actor
    value is accepted from the request: ``publisher`` is added to the result and
    history edge from the authenticated execution context by the caller.
    """
    metadata = {key: request[key] for key in _METADATA if key in request}
    if _is_v2_request(request) or "steps" in data:
        metadata["label"] = data["label"]
        metadata["merge"] = request.get("merge", "fields")
        metadata["merge_mode"] = data["merge_mode"]
        if "reads" in request:
            metadata["reads"] = request["reads"]
    return metadata


def _validate_record_metadata(request, records):
    """Require the provider's authoritative v2 metadata, while leaving ABI-1 untouched."""
    if not _is_v2_request(request, records):
        return
    if records.get("label") != request.get("label", "Timeline edit"):
        reject("invalid_records", "provider label differs from the request", status=422)
    if records.get("merge_mode") != _effective_merge_mode(request):
        reject("invalid_records", "provider merge mode differs from the effective request mode", status=422)
    if "steps" not in records:
        reject("invalid_records", "provider did not return authoritative step records", status=422)
    if any("dependencies" not in step for step in records["steps"]):
        reject("invalid_records", "provider step dependencies are missing", status=422)


_SHELL_SCOPE_TABLES = ("timeline_shots", "timeline_references", "timeline_render_publications",
                       "timeline_document_input_links", "timeline_commit_history")


def has_authored_content(value):
    if isinstance(value, dict):
        return any(has_authored_content(item) for item in value.values())
    if isinstance(value, list):
        return any(has_authored_content(item) for item in value)
    return value is not None


def timeline_scope_is_empty(conn, timeline_id, *, project_id=None):
    """True when nothing is authored under the timeline or its legacy document."""
    if project_id is not None:
        document = conn.execute("SELECT content_json FROM project_documents WHERE id=? AND project_id=?",
                                (f"timeline:{timeline_id}", project_id)).fetchone()
        if document is not None:
            # Baseline verification already rejects duplicate/non-finite JSON.
            # Use the same parser here so corrupt legacy bytes cannot hide
            # authored content behind a last-key-wins decode.
            from .timeline_commit_baseline import _json
            try:
                content = _json(document["content_json"])
            except (TypeError, ValueError):
                return False
            if has_authored_content(content):
                return False
    # Any row keyed to the timeline is authored data.
    for table in _SHELL_SCOPE_TABLES:
        if conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table,)).fetchone() and \
                conn.execute(f"SELECT 1 FROM {table} WHERE timeline_id=? LIMIT 1", (timeline_id,)).fetchone():
            return False
    # create_timeline snapshots the empty shell as timeline_revisions v1; only a non-empty snapshot is authored.
    if conn.execute("SELECT 1 FROM timeline_revisions WHERE timeline_id=? AND (shots_json!='[]' OR references_json!='[]') LIMIT 1",
                    (timeline_id,)).fetchone():
        return False
    for child in ("composition_revision_occurrences", "composition_revision_dependencies"):
        if conn.execute(f"SELECT 1 FROM {child} c JOIN parent_composition_revisions r ON r.id=c.parent_revision_id "
                        "WHERE r.timeline_id=? LIMIT 1", (timeline_id,)).fetchone():
            return False
    return True


class TimelineCommitStore:
    def __init__(self, store, *, validate_prepared, validate_event=None):
        self.store = store
        # Validation uses the wire worker's authoritative schema, including
        # Agent-owned leaves. It must raise on invalid data, never normalize it.
        self.validate_prepared = validate_prepared
        self.validate_event = validate_event

    @property
    def conn(self):
        return self.store.conn

    def _membership(self, project_id, timeline_id):
        row = self.conn.execute("SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                                "WHERE t.id=? AND t.project_id=? AND t.archived_at IS NULL",
                                (timeline_id, project_id)).fetchone()
        if row is None:
            reject("history_unavailable")
        return row["realm_id"]

    def lookup(self, context, *, authorize):
        with self.store._mutex:
            authorize()
            request = context["request"]
            # Lookup is the only path allowed to inspect an archived scope:
            # it must first authenticate the current actor, then prove the
            # project/timeline row exists, and only then read the exact key.
            # New writes continue through _membership's active-row guard.
            row = self.conn.execute(
                "SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                "WHERE t.id=? AND t.project_id=?",
                (request["timeline_id"], request["project_id"]),
            ).fetchone()
            if row is None or row["realm_id"] != context["realm_id"]:
                reject("authority_changed")
            return self._lookup(context)

    def _lookup(self, context):
        row = self.conn.execute("SELECT * FROM command_idempotency WHERE command_kind='timeline.commit' "
                                "AND aggregate_id=? AND idempotency_key=?", (scope(context), context["idempotency_key"])).fetchone()
        if row is None:
            return None
        if row["request_hash"] != context["request_hash"]:
            reject("idempotency_mismatch")
        edge = self.conn.execute("SELECT * FROM timeline_commit_history WHERE publication_id=?", (row["txn_id"],)).fetchone()
        if edge is None or edge["project_id"] != context["request"]["project_id"] or edge["timeline_id"] != context["request"]["timeline_id"]:
            raise ProtocolError("accepted commit history is missing or corrupt")
        self._verify_accepted(row, edge, allow_archived=True)
        return self._envelope(row, edge["project_id"])

    def _verify_accepted(self, row, edge, *, allow_archived=False):
        from .timeline_commit import CommitRejected
        try:
            data, records = json.loads(row["result_json"]), json.loads(edge["records_json"])
            previous = {"revision_id": edge["previous_revision_id"], "publication_id": edge["previous_publication_id"]}
            document = data["canonical_document"]
            valid = (edge["intent"] == "recorded" and row["command_kind"] == "timeline.commit"
                     and row["txn_id"] == edge["publication_id"]
                     and row["aggregate_id"] == canonical_json([edge["project_id"], edge["timeline_id"]])
                     and row["primary_stream_id"] == edge["timeline_id"]
                     and row["first_project_seq"] == row["last_project_seq"] == edge["project_seq"]
                     and data["accepted_revision_id"] == document["parent_revision"]["revision_id"] == edge["revision_id"]
                     and document["project_id"] == edge["project_id"] and document["timeline_id"] == edge["timeline_id"]
                     and data["document_digest"] == digest(document)
                     and canonical_json(data["commands"]) == canonical_json([r["command"] for r in records["commands"]])
                     and data["previous_revision_id"] == previous["revision_id"]
                     and data["previous_publication_id"] == previous["publication_id"]
                     and data["publisher"] == edge["publisher"]
                     and all(data[k] == edge[k] for k in ("provider_version", "compiler_version"))
                     and {k: data[k] for k in json.loads(edge["metadata_json"])
                          if k in data and k in _METADATA} == {
                         k: json.loads(edge["metadata_json"])[k] for k in json.loads(edge["metadata_json"])
                         if k in _METADATA
                     })
            base = {"revision_id": data["base_revision_id"], "publication_id": data["base_publication_id"]}
            historical_status = "accepted" if previous == base else "rebased"
            modern_status = "accepted" if previous == base else "merged"
            valid = valid and data["status"] in {historical_status, modern_status}
            valid = valid and data["rebased_onto"] == (None if previous == base else previous)
            metadata = json.loads(edge["metadata_json"])
            if "merge_mode" in metadata:
                valid = valid and data.get("merge_mode") == metadata["merge_mode"]
            if "merge" in metadata:
                valid = valid and metadata["merge"] in {"fields", "atomic"}
            if "reads" in metadata:
                valid = valid and data.get("reads", metadata["reads"]) == metadata["reads"]
            if "steps" in records:
                valid = valid and data.get("steps") == records["steps"]
            if "label" in records:
                valid = valid and data.get("label") == records["label"]
            if "merge_mode" in records:
                valid = valid and data.get("merge_mode") == records["merge_mode"]
            if "steps" in records:
                from .timeline_commit_auth import validate
                replay_request = {**metadata, "commands": data["commands"],
                                  "base_revision_id": base["revision_id"], "base_publication_id": base["publication_id"]}
                source = self.revision_closure(edge["project_id"], edge["timeline_id"], previous["revision_id"],
                                               allow_archived=allow_archived)
                continuations = self._binding_continuations(
                    edge["project_id"], edge["timeline_id"], base["publication_id"], previous,
                    allow_archived=allow_archived,
                )
                history = self._inverse_stage_history(edge["project_id"], edge["timeline_id"], records,
                                                      allow_archived=allow_archived)
                validate(replay_request, {"records": records, "expected_head": previous, "canonical_document": document},
                         source, continuations=continuations, history=history)
            ids = json.loads(row["event_ids_json"])
            seq = row["resulting_stream_seq"]
            # Replay verifies the accepted prefix, independent of later writes.
            events = self.conn.execute("SELECT * FROM timeline_events WHERE timeline_id=? ORDER BY id LIMIT ?",
                                       (edge["timeline_id"], seq)).fetchall()
            valid = valid and isinstance(ids, list) and 0 < len(ids) <= seq <= len(events)
            valid = valid and ids == [str(e["id"]) for e in events[seq - len(ids):seq]]
            project_seq = self.conn.execute("SELECT next_seq FROM project_sequences WHERE project_id=?",
                                            (edge["project_id"],)).fetchone()
            valid = valid and project_seq is not None and 0 < edge["project_seq"] < project_seq[0]
            previous_hash = ""
            for event in events:
                hashed = {"timeline_id": edge["timeline_id"], "kind": event["kind"],
                          "payload": json.loads(event["payload_json"]), "previous_hash": previous_hash,
                          "created_at": event["created_at"]}
                valid = valid and event["previous_hash"] == previous_hash and event["event_hash"] == digest(hashed)[7:]
                previous_hash = event["event_hash"]
            event = self.conn.execute("SELECT * FROM timeline_events WHERE id=? AND timeline_id=?",
                                      (ids[-1], edge["timeline_id"])).fetchone()
            valid = valid and event is not None and event["kind"] == "timeline.commit.accepted"
            if valid:
                payload = json.loads(event["payload_json"])
                valid = payload == {"project_id": edge["project_id"], "timeline_id": edge["timeline_id"],
                                    "previous": previous, "revision_id": edge["revision_id"],
                                    "publisher": edge["publisher"], "intent": "recorded",
                                    "records_digest": digest(records)}
            if not valid:
                raise ValueError()
            prepared = {**data, "records": records, "expected_head": previous}
            if has_materialization(prepared):
                project, timeline = edge["project_id"], edge["timeline_id"]
                allocations = materialization_join(prepared, project, timeline,
                    lambda revision: self.revision_closure(project, timeline, revision,
                                                           allow_archived=allow_archived))
                if canonical_json(document) != canonical_json(self.revision_closure(
                        project, timeline, edge["revision_id"], allow_archived=allow_archived)):
                    raise ValueError()
                self._check_inherited_allocations(project, timeline, records, allocations, edge["project_seq"],
                                                   allow_archived=allow_archived)
        except (KeyError, TypeError, ValueError, IndexError, ValidationError, CommitRejected) as exc:
            raise ProtocolError("accepted commit record is corrupt") from exc

    def _check_inherited_allocations(self, project, timeline, records, allocations, before_seq=None,
                                     *, allow_archived=False):
        inverse_refs = {d["key"].removeprefix("materialization.source:")
                        for r in records["commands"] if r["command"]["op"] == "timeline.inverse"
                        for d in r["dependencies"] if d["key"].startswith("materialization.source:")}
        if not inverse_refs:
            return
        inherited = {}
        for publication in records["undo_of"]:
            if before_seq is not None:
                row = self.conn.execute("SELECT project_seq FROM timeline_commit_history WHERE publication_id=?",
                                        (publication,)).fetchone()
                if row is None or row[0] >= before_seq:
                    reject("invalid_records")
            entry = self.history_entry(project, timeline, publication, allow_archived=allow_archived)
            data = entry["receipt"]["result"]
            target = {**data, "records": entry["records"], "expected_head": entry["previous"]}
            if has_materialization(target):
                for shot, allocation in materialization_join(target, project, timeline,
                        lambda revision: self.revision_closure(project, timeline, revision,
                                                               allow_archived=allow_archived)).items():
                    if shot in inherited and canonical_json(inherited[shot]) != canonical_json(allocation):
                        reject("invalid_records")
                    inherited[shot] = allocation
        if any(canonical_json(allocations.get(ref.removeprefix("shot:"))) !=
               canonical_json(inherited.get(ref.removeprefix("shot:"))) for ref in inverse_refs):
            reject("invalid_records", "inverse allocation lacks authenticated provenance")

    @staticmethod
    def _envelope(row, project_id):
        data = (json.loads(row["result_json"]) if row["command_kind"] == "parent_composition.publish" else
                command_result(row["result_json"], kind="timeline.commit", created_at=row["created_at"]))
        receipt = {"receipt_id": row["txn_id"], "command_kind": row["command_kind"],
                   "idempotency_key": row["idempotency_key"], "request_hash": row["request_hash"],
                   "project_id": project_id, "project_seq": [row["first_project_seq"], row["last_project_seq"]],
                   "event_ids": json.loads(row["event_ids_json"]), "result": data, "created_at": row["created_at"]}
        return detached({"data": data, "receipt": receipt})

    def head(self, project_id, timeline_id):
        with self.store._mutex:
            self._membership(project_id, timeline_id)
            row = self.conn.execute("SELECT revision_id, publication_id FROM parent_composition_heads "
                                    "WHERE project_id=? AND timeline_id=?", (project_id, timeline_id)).fetchone()
            if row is None or not row["revision_id"] or not row["publication_id"]:
                reject("history_unavailable")
            entry = self.history_entry(project_id, timeline_id, row["publication_id"])
            if entry["revision_id"] != row["revision_id"]:
                reject("history_unavailable")
            from .timeline_commit_baseline import _publication_events, _shot_projection, _text_bindings
            from .timeline_catalog import verify_catalog_tail
            ledger = self.conn.execute("SELECT resulting_stream_seq, last_project_seq FROM command_idempotency WHERE txn_id=?",
                                       (row["publication_id"],)).fetchone()
            try:
                events, _, _ = _publication_events(self.conn, project_id, timeline_id)
                catalog = verify_catalog_tail(self.conn, project_id, timeline_id, events, ledger[0], ledger[1],
                                              legacy=entry["intent"] == "legacy_unknown")
                if catalog:
                    from .cas import ContentAddressedStore
                    document = self.revision_closure(project_id, timeline_id, row["revision_id"])
                    if entry["intent"] == "recorded" and document != entry["receipt"]["result"]["canonical_document"]:
                        reject("history_unavailable", "canonical film differs from accepted publication")
                    for shot in document["shot_revisions"]:
                        _shot_projection(self.conn, project_id, shot["shot_id"])
                        _text_bindings(self.conn, project_id, shot, ContentAddressedStore(self.store.cas_root).read)
            except ConflictError as exc:
                from .timeline_commit import CommitRejected
                raise CommitRejected({"http_status": 409, "code": "conflict",
                                      "message": "timeline has untracked writes",
                                      "details": {"base": None, "current": None, "conflicts": [], **exc.details}}) from exc
            except (KeyError, TypeError, ValueError, IndexError):
                reject("history_unavailable", "timeline catalog facts are corrupt")
            return dict(row)

    def history_entry(self, project_id, timeline_id, publication_id, *, allow_archived=False):
        with self.store._mutex:
            if allow_archived:
                row = self.conn.execute(
                    "SELECT p.realm_id FROM timelines t JOIN projects p ON p.id=t.project_id "
                    "WHERE t.id=? AND t.project_id=?", (timeline_id, project_id)).fetchone()
                if row is None:
                    reject("history_unavailable")
            else:
                self._membership(project_id, timeline_id)
            row = self.conn.execute("SELECT * FROM timeline_commit_history WHERE publication_id=? "
                                    "AND project_id=? AND timeline_id=?", (publication_id, project_id, timeline_id)).fetchone()
            if row is None:
                reject("history_unavailable")
            ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (publication_id,)).fetchone()
            if ledger is None or ledger["first_project_seq"] != row["project_seq"]:
                reject("history_unavailable")
            if row["intent"] == "recorded" or ledger["command_kind"] == "timeline.commit":
                self._verify_accepted(ledger, row, allow_archived=allow_archived)
            previous = None if row["previous_publication_id"] is None else {
                "revision_id": row["previous_revision_id"], "publication_id": row["previous_publication_id"]}
            records = json.loads(row["records_json"]) if row["records_json"] is not None else None
            entry = {"publication_id": publication_id, "revision_id": row["revision_id"], "previous": previous,
                     "receipt": self._envelope(ledger, project_id)["receipt"], "intent": row["intent"],
                     "records": records, "provider_version": row["provider_version"],
                     "compiler_version": row["compiler_version"], "publisher": row["publisher"],
                     **json.loads(row["metadata_json"])}
            # Modern records carry the authenticated provider projection.  A
            # legacy edge has no recorder and must remain null/absent rather
            # than receiving invented step or undo authority.
            if records is not None and "steps" in records:
                entry["steps"] = records["steps"]
            return entry

    def history(self, project_id, timeline_id, through, after_publication_id=None, cursor=None, limit=100):
        if type(limit) is not int or not 1 <= limit <= 200:
            raise ValidationError("history limit must be 1–200")
        with self.store._mutex:
            bound = self.history_entry(project_id, timeline_id, through["publication_id"])
            if bound["revision_id"] != through["revision_id"]:
                reject("history_unavailable")
            after = self.history_entry(project_id, timeline_id, after_publication_id) if after_publication_id else None
            low = after["receipt"]["project_seq"][0] if after else 0
            high = bound["receipt"]["project_seq"][0]
            cursor_scope = [project_id, timeline_id, through, after_publication_id]
            start = low
            if cursor is not None:
                try:
                    decoded = json.loads(base64.urlsafe_b64decode(cursor.encode()))
                    if decoded["scope"] != cursor_scope or type(decoded["seq"]) is not int or not low < decoded["seq"] <= high:
                        raise ValueError()
                    start = decoded["seq"]
                except (ValueError, KeyError, TypeError) as exc:
                    raise ValidationError("invalid history cursor") from exc
            if low > high:
                reject("history_unavailable")
            rows = self.conn.execute("SELECT publication_id FROM timeline_commit_history WHERE project_id=? AND timeline_id=? "
                                     "AND project_seq>? AND project_seq<=? ORDER BY project_seq LIMIT ?",
                                     (project_id, timeline_id, start, high, limit + 1)).fetchall()
            items = [self.history_entry(project_id, timeline_id, row[0]) for row in rows[:limit]]
            previous = self.conn.execute("SELECT publication_id, revision_id FROM timeline_commit_history WHERE project_id=? "
                                        "AND timeline_id=? AND project_seq<=? ORDER BY project_seq DESC LIMIT 1",
                                        (project_id, timeline_id, start)).fetchone()
            expected = dict(previous) if previous else None
            for entry in items:
                if entry["previous"] != expected:
                    reject("history_unavailable")
                expected = {"publication_id": entry["publication_id"], "revision_id": entry["revision_id"]}
            if len(rows) <= limit and expected != through:
                reject("history_unavailable")
            next_cursor = None
            if len(rows) > limit:
                next_cursor = base64.urlsafe_b64encode(canonical_json({"scope": cursor_scope,
                    "seq": items[-1]["receipt"]["project_seq"][0]}).encode()).decode()
            return {"items": items, "next_cursor": next_cursor, "head": detached(through)}

    def revision_closure(self, project_id, timeline_id, revision_id, *, allow_archived=False):
        with self.store._mutex:
            if allow_archived:
                row = self.conn.execute(
                    "SELECT 1 FROM timelines WHERE id=? AND project_id=?",
                    (timeline_id, project_id),
                ).fetchone()
                if row is None:
                    reject("history_unavailable")
            else:
                self._membership(project_id, timeline_id)
            parent = self.conn.execute("SELECT * FROM parent_composition_revisions WHERE id=? AND project_id=? AND timeline_id=?",
                                       (revision_id, project_id, timeline_id)).fetchone()
            if parent is None:
                reject("history_unavailable")
            if parent["commit_manifest_json"] is None:
                from .cas import ContentAddressedStore
                from .timeline_commit_baseline import verify_revision_source
                document = verify_revision_source(self.conn, project_id, timeline_id, revision_id,
                                                   read_object=ContentAddressedStore(self.store.cas_root).read)
                self._validate_closure(document, allow_archived=allow_archived)
                return document
            manifest = json.loads(parent["commit_manifest_json"])
            document = {"schema_version": 1, "project_id": project_id, "timeline_id": timeline_id,
                        "parent_revision": self._image(parent), "shot_revisions": [],
                        "internal_timeline_revisions": [], "dependency_manifest": manifest}
            for family, table in (("shot_revisions", "shot_revisions"), ("internal_timeline_revisions", "internal_timeline_revisions")):
                pins = manifest["shots" if family == "shot_revisions" else "internal_timelines"]
                for pin in pins:
                    row = self.conn.execute(f"SELECT * FROM {table} WHERE id=? AND project_id=?", (pin["revision_id"], project_id)).fetchone()
                    if row is None:
                        reject("history_unavailable")
                    image = self._image(row)
                    image.update({key: row[key] for key in ("shot_id", "internal_timeline_revision_id") if key in row.keys()})
                    if family == "internal_timeline_revisions":
                        image["timeline_id"] = row["timeline_id"]
                    document[family].append(image)
            self._validate_closure(document, allow_archived=allow_archived)
            self._verify_inputs(document)
            return document

    def source_revision_closure(self, project_id, timeline_id, revision_id, publication_id,
                                content_digest):
        """Return one authenticated historical source closure.

        The source pair is deliberately checked separately from the request's
        destination head.  A revision ID alone is not a source authority: the
        accepted publication edge and the immutable parent digest must agree
        with the caller's exact reference.
        """
        with self.store._mutex:
            entry = self.history_entry(project_id, timeline_id, publication_id)
            if entry["revision_id"] != revision_id:
                reject("dependency_unavailable", "source publication and revision pins disagree")
            document = self.revision_closure(project_id, timeline_id, revision_id)
            if document is not None:
                parent = document.get("parent_revision")
                if not isinstance(parent, dict) or parent.get("content_digest") != content_digest:
                    reject("dependency_unavailable", "source revision content digest disagrees")
                return document
            reject("dependency_unavailable", "source revision closure is unavailable")

    def _verify_inputs(self, document):
        for pin in document["dependency_manifest"]["documents"]:
            row = self.conn.execute("SELECT c.content_json, c.content_size, b.kind FROM timeline_document_input_contents c "
                "JOIN timeline_document_input_bindings b ON b.content_digest=c.content_digest "
                "JOIN timeline_document_input_links l ON l.project_id=b.project_id AND l.document_id=b.document_id "
                "AND l.document_version=b.document_version AND l.content_digest=b.content_digest "
                "WHERE l.project_id=? AND l.timeline_id=? AND l.revision_id=? AND b.document_id=? "
                "AND b.document_version=? AND b.content_digest=? LIMIT 1",
                (document["project_id"], document["timeline_id"], document["parent_revision"]["revision_id"],
                 pin["document_id"], pin["version"], pin["content_digest"])).fetchone()
            if row is None or digest(json.loads(row["content_json"])) != pin["content_digest"] or len(row["content_json"].encode()) != row["content_size"]:
                reject("dependency_unavailable", "retained input is missing or corrupt")
            from .timeline_commit_inputs import PROJECT_PACK_KIND, validate_pack_snapshot_objects
            if row["kind"] == PROJECT_PACK_KIND:
                validate_pack_snapshot_objects(self.conn, document["project_id"], json.loads(row["content_json"]))

    def integrity_errors(self):
        errors = []
        previous = {}
        for edge in self.conn.execute("SELECT * FROM timeline_commit_history ORDER BY project_id, timeline_id, project_seq"):
            try:
                key = (edge["project_id"], edge["timeline_id"])
                expected = previous.get(key)
                actual = (edge["previous_publication_id"], edge["previous_revision_id"])
                if actual != (expected if expected else (None, None)):
                    raise ValueError("history ancestry mismatch")
                previous[key] = (edge["publication_id"], edge["revision_id"])
                ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (edge["publication_id"],)).fetchall()
                if len(ledger) != 1 or ledger[0]["first_project_seq"] != edge["project_seq"]:
                    raise ValueError("history receipt missing or ambiguous")
                if edge["intent"] == "recorded":
                    self._verify_accepted(ledger[0], edge)
                    self._verify_inputs(json.loads(ledger[0]["result_json"])["canonical_document"])
                elif edge["records_json"] is not None or ledger[0]["command_kind"] != "parent_composition.publish":
                    raise ValueError("invented legacy provenance")
            except Exception as exc:
                errors.append({"table": "timeline_commit_history", "id": edge["publication_id"], "reason": str(exc)})
        for key, expected in previous.items():
            head = self.conn.execute("SELECT publication_id, revision_id FROM parent_composition_heads WHERE project_id=? AND timeline_id=?", key).fetchone()
            if head is None or tuple(head) != expected:
                errors.append({"table": "parent_composition_heads", "id": key[1], "reason": "publication head mismatch"})
        for row in self.conn.execute("SELECT * FROM timeline_document_input_contents"):
            try:
                value = detached(json.loads(row["content_json"]))
                if digest(value) != row["content_digest"] or canonical_json(value) != row["content_json"] or len(row["content_json"].encode()) != row["content_size"]:
                    raise ValueError("retained input digest mismatch")
            except Exception as exc:
                errors.append({"table": "timeline_document_input_contents", "id": row["content_digest"], "reason": str(exc)})
        for row in self.conn.execute("SELECT l.* FROM timeline_document_input_links l LEFT JOIN timeline_commit_history h "
                                     "ON h.publication_id=l.publication_id AND h.project_id=l.project_id "
                                     "AND h.timeline_id=l.timeline_id AND h.revision_id=l.revision_id WHERE h.publication_id IS NULL"):
            errors.append({"table": "timeline_document_input_links", "id": row["publication_id"], "reason": "orphan retained input link"})
        return errors

    def shot_closure(self, project_id, shot_id, revision_id):
        with self.store._mutex:
            row = self.conn.execute("SELECT * FROM shot_revisions WHERE id=? AND project_id=? AND shot_id=?",
                                    (revision_id, project_id, shot_id)).fetchone()
            if row is None:
                reject("dependency_unavailable")
            internal = self.conn.execute("SELECT * FROM internal_timeline_revisions WHERE id=? AND project_id=?",
                                         (row["internal_timeline_revision_id"], project_id)).fetchone()
            if internal is None:
                reject("dependency_unavailable")
            shot = {**self._image(row), "shot_id": shot_id, "internal_timeline_revision_id": internal["id"]}
            image = {**self._image(internal), "timeline_id": internal["timeline_id"]}
            if digest(shot["payload"]) != shot["content_digest"] or digest(image["payload"]) != image["content_digest"]:
                reject("dependency_unavailable")
            if shot["payload"].get("internal_timeline_revision_id") != internal["id"]:
                reject("dependency_unavailable")
            manifests = self.conn.execute("SELECT DISTINCT json_extract(p.commit_manifest_json, '$.media'), "
                "json_extract(p.commit_manifest_json, '$.documents') FROM parent_composition_revisions p "
                "JOIN composition_revision_occurrences o ON o.parent_revision_id=p.id "
                "WHERE p.project_id=? AND o.shot_id=? AND o.shot_revision_id=? AND p.commit_manifest_json IS NOT NULL LIMIT 2",
                (project_id, shot_id, revision_id)).fetchall()
            if len(manifests) != 1:
                reject("history_unavailable", "shot input closure is unavailable or ambiguous")
            parent = self.conn.execute("SELECT p.timeline_id, p.id FROM parent_composition_revisions p "
                "JOIN composition_revision_occurrences o ON o.parent_revision_id=p.id "
                "WHERE p.project_id=? AND o.shot_id=? AND o.shot_revision_id=? AND p.commit_manifest_json IS NOT NULL ORDER BY p.id LIMIT 1",
                (project_id, shot_id, revision_id)).fetchone()
            if parent is None:
                reject("history_unavailable")
            document = self.revision_closure(project_id, parent["timeline_id"], parent["id"])
            return {"shot_revision": shot, "internal_timeline_revision": image,
                    "media": document["dependency_manifest"]["media"], "documents": document["dependency_manifest"]["documents"]}

    def _verify_parent_rows(self, document):
        parent_id = document["parent_revision"]["revision_id"]
        occurrences = document["parent_revision"]["payload"]["occurrences"]
        rows = self.conn.execute("SELECT * FROM composition_revision_occurrences WHERE parent_revision_id=? ORDER BY ordinal", (parent_id,)).fetchall()
        if len(rows) != len(occurrences):
            reject("history_unavailable")
        for ordinal, (row, occurrence) in enumerate(zip(rows, occurrences)):
            expected = {"parent_revision_id": parent_id, "project_id": document["project_id"], "ordinal": ordinal,
                        **{k: occurrence[k] for k in ("occurrence_id", "shot_id", "shot_revision_id", "duration_ms", "track")},
                        "gain": occurrence.get("gain", 1),
                        "muted": int(occurrence.get("muted", occurrence.get("mute", False))),
                        "placement_json": canonical_json(occurrence["placement"]),
                        **{k + "_json": canonical_json(occurrence.get(k, default)) for k, default in
                           (("source_offset", 0), ("speed", 1), ("transform", {}), ("provenance", {}))}}
            if dict(row) != expected:
                reject("history_unavailable")
        manifest = document["dependency_manifest"]
        expected = [("shot_revision", p["revision_id"], p["content_digest"]) for p in manifest["shots"]]
        expected += [("internal_timeline_revision", p["revision_id"], p["content_digest"]) for p in manifest["internal_timelines"]]
        expected += [("media", p["media_id"], p["content_digest"]) for p in manifest["media"]]
        rows = self.conn.execute("SELECT dependency_kind, dependency_id, content_digest, ordinal FROM composition_revision_dependencies "
                                 "WHERE parent_revision_id=? ORDER BY ordinal", (parent_id,)).fetchall()
        if [tuple(row) for row in rows] != [(*pin, ordinal) for ordinal, pin in enumerate(expected)]:
            reject("history_unavailable")

    @staticmethod
    def _image(row):
        return {"revision_id": row["id"], "content_digest": row["content_digest"], "payload": json.loads(row["payload_json"])}

    def _validate_closure(self, document, *, allow_archived=False):
        from .visual_seam import parent_clips

        project_id, timeline_id = document["project_id"], document["timeline_id"]
        if allow_archived:
            row = self.conn.execute(
                "SELECT 1 FROM timelines WHERE id=? AND project_id=?",
                (timeline_id, project_id),
            ).fetchone()
            if row is None:
                reject("history_unavailable")
        else:
            self._membership(project_id, timeline_id)
        parent = document["parent_revision"]
        try:
            parent_clips(parent["payload"])
        except (ConflictError, ValidationError) as exc:
            reject("invalid_closure", str(exc), status=422)
        shots, internals = document["shot_revisions"], document["internal_timeline_revisions"]
        manifest = document["dependency_manifest"]
        for clip in parent["payload"]["clips"]:
            if not isinstance(clip, dict) or set(clip) & {"occurrence_id", "shot_revision_id", "parent_revision_id", "composition_revision_id"}:
                reject("invalid_closure", "ordinary clips cannot contain nested compositions", status=422)
        for images, table, identity in (([parent], "parent_composition_revisions", "timeline_id"),
                                        (shots, "shot_revisions", "shot_id"), (internals, "internal_timeline_revisions", "timeline_id")):
            if len({image["revision_id"] for image in images}) != len(images):
                reject("invalid_closure", status=422)
            for image in images:
                if digest(image["payload"]) != image["content_digest"]:
                    reject("invalid_closure", "revision content digest mismatch", status=422)
                owner_id = image.get(identity, timeline_id)
                existing = self.conn.execute(f"SELECT * FROM {table} WHERE id=?", (image["revision_id"],)).fetchone()
                if existing is not None and (existing["project_id"] != project_id or existing[identity] != owner_id
                        or existing["payload_json"] != canonical_json(image["payload"]) or existing["content_digest"] != image["content_digest"]):
                    reject("revision_identity_mismatch")
                if table == "parent_composition_revisions" and existing is not None and existing["commit_manifest_json"] is not None:
                    if existing["commit_manifest_json"] != canonical_json(manifest):
                        reject("revision_identity_mismatch", "revision dependency closure changed")
                if table == "internal_timeline_revisions":
                    payload = image["payload"]
                    nested_fields = {"occurrences", "occurrence_records", "parent_composition", "nested_composition",
                                     "occurrence_id", "shot_revision_id", "parent_revision_id", "composition_revision_id"}
                    # Only authored structure is reserved; params and provenance remain opaque.
                    if set(payload) & nested_fields or any(set(clip) & nested_fields for clip in payload.get("clips", [])):
                        reject("invalid_closure", "internal timeline cannot contain a nested composition", status=422)
                    owner = self.conn.execute("SELECT project_id FROM timelines WHERE id=?", (owner_id,)).fetchone()
                    shot_id = owner_id.removeprefix("shot:") if owner_id.startswith("shot:") else None
                    if owner is None and shot_id:
                        owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (shot_id,)).fetchone()
                        if owner is None and any(s["shot_id"] == shot_id for s in shots):
                            owner = {"project_id": project_id}
                    if owner is None or owner["project_id"] != project_id:
                        reject("invalid_closure", "internal timeline scope mismatch")
                if table == "shot_revisions":
                    if existing is not None and existing["internal_timeline_revision_id"] != image["internal_timeline_revision_id"]:
                        reject("revision_identity_mismatch")
                    owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (owner_id,)).fetchone()
                    if owner is not None and owner["project_id"] != project_id:
                        reject("invalid_closure", "shot scope mismatch")
                    if image["payload"].get("internal_timeline_revision_id") != image["internal_timeline_revision_id"]:
                        reject("invalid_closure", status=422)
                    payload = image["payload"]
                    if set(payload) & {"occurrences", "occurrence_records", "parent_composition", "parent_revision_id", "composition_revision_id"}:
                        reject("invalid_closure", "nested shot composition", status=422)
                    if not isinstance(payload.get("items", []), list) or any(not isinstance(item, dict)
                            or not isinstance(item.get("item_id", item.get("id")), str) or not item.get("media_id")
                            for item in payload.get("items", [])):
                        reject("invalid_closure", "shot items cannot be projected", status=422)
        shot_keys = {(s["shot_id"], s["revision_id"]) for s in shots}
        occurrences = parent["payload"]["occurrences"]
        for occurrence in occurrences:
            speed = occurrence.get("speed", 1)
            valid_speed = (type(speed) in (int, float) and speed > 0) or (isinstance(speed, dict)
                and set(speed) == {"numerator", "denominator"} and all(type(v) is int and v > 0 for v in speed.values()))
            if not valid_speed or not occurrence["placement"] or not isinstance(occurrence.get("muted", occurrence.get("mute", False)), bool):
                reject("invalid_closure", "invalid occurrence timing or placement", status=422)
            if "muted" in occurrence and "mute" in occurrence and occurrence["muted"] != occurrence["mute"]:
                reject("invalid_closure", "ambiguous occurrence mute", status=422)
        if shot_keys != {(o["shot_id"], o["shot_revision_id"]) for o in occurrences}:
            reject("invalid_closure", "incomplete or extraneous shot closure", status=422)
        if len({o["occurrence_id"] for o in occurrences}) != len(occurrences):
            reject("invalid_closure", "duplicate occurrences", status=422)
        if {s["internal_timeline_revision_id"] for s in shots} != {i["revision_id"] for i in internals}:
            reject("invalid_closure", "incomplete or extraneous internal closure", status=422)
        for images, key, fields, sort_keys in ((shots, "shots", ("shot_id", "revision_id", "internal_timeline_revision_id", "content_digest"), ("shot_id", "revision_id")),
                (internals, "internal_timelines", ("timeline_id", "revision_id", "content_digest"), ("timeline_id", "revision_id"))):
            ordered = sorted(images, key=lambda image: tuple(image[k] for k in sort_keys))
            if images != ordered or manifest[key] != [{k: image[k] for k in fields} for image in ordered]:
                reject("invalid_closure", "manifest does not equal complete closure", status=422)
        media = manifest["media"]
        if media != sorted(media, key=lambda item: item["media_id"]) or len({m["media_id"] for m in media}) != len(media):
            reject("invalid_closure", status=422)
        for pin in media:
            if not _DIGEST.fullmatch(pin["media_id"]) or pin["content_digest"] != pin["media_id"]:
                reject("invalid_closure", status=422)
            row = self.conn.execute("SELECT o.size FROM objects o JOIN project_objects p ON p.digest=o.digest "
                                    "WHERE p.project_id=? AND p.relation='managed' AND o.digest=?", (project_id, pin["media_id"][7:])).fetchone()
            if row is None:
                reject("dependency_unavailable")
            from .cas import ContentAddressedStore
            data = ContentAddressedStore(self.store.cas_root).read(pin["media_id"][7:])
            if len(data) != row["size"] or "sha256:" + hashlib.sha256(data).hexdigest() != pin["media_id"]:
                reject("dependency_unavailable")
        payload_media = set()
        def collect(value):
            if isinstance(value, dict):
                for key, child in value.items():
                    if key in {"media_id", "object_id"} and isinstance(child, str):
                        normalized = child if child.startswith("sha256:") else "sha256:" + child
                        if _DIGEST.fullmatch(normalized):
                            payload_media.add(normalized)
                    collect(child)
            elif isinstance(value, list):
                for child in value:
                    collect(child)
        for image in [parent, *shots, *internals]:
            collect(image["payload"])
        if not payload_media <= {m["media_id"] for m in media}:
            reject("invalid_closure", "unaccounted media", status=422)
        pins = manifest["documents"]
        if pins != sorted(pins, key=lambda p: (p["document_id"], p["version"], p["content_digest"])) or len({canonical_json(p) for p in pins}) != len(pins):
            reject("invalid_closure", status=422)
        existing = self.conn.execute("SELECT 1 FROM parent_composition_revisions WHERE id=?", (parent["revision_id"],)).fetchone()
        if existing is not None:
            self._verify_parent_rows(document)

    def _binding_continuations(self, project, timeline, base_publication, expected, *, allow_archived=False):
        continuations, cursor = {}, expected
        while cursor["publication_id"] != base_publication:
            entry = self.history_entry(project, timeline, cursor["publication_id"], allow_archived=allow_archived)
            if entry["records"]:
                for record in entry["records"]["commands"]:
                    for binding in record["bindings"]:
                        if binding.get("key") == "commit.materialization":
                            continuations.setdefault(binding["physical_ref"], set()).add(binding["successor"])
            cursor = entry["previous"]
            if cursor is None:
                reject("history_unavailable", "base is outside evaluated head ancestry")
        return continuations

    def _inverse_stage_history(self, project, timeline, records, *, allow_archived=False):
        """Pass only store-authenticated undo sources to inverse-stage auth."""
        if not any(binding.get("key") == "inverse.stage"
                   for record in records.get("commands", []) for binding in record.get("bindings", [])):
            return None
        publications = records.get("undo_of")
        if not isinstance(publications, list):
            reject("history_unavailable", "inverse stage history targets are unavailable")
        return {publication: self.history_entry(project, timeline, publication, allow_archived=allow_archived)
                for publication in publications}

    def _validate(self, context, prepared, inputs):
        # Callers run _check_shot_destinations first, which validates the schema.
        request = context["request"]
        document = prepared["canonical_document"]
        if (document["project_id"], document["timeline_id"]) != (request["project_id"], request["timeline_id"]):
            reject("invalid_closure", status=422)
        if prepared["document_digest"] != digest(document):
            reject("invalid_closure", "whole-document digest mismatch", status=422)
        self._validate_closure(document)
        records = prepared["records"]
        commands = records["commands"]
        if not commands or [r["ordinal"] for r in commands] != list(range(len(commands))):
            reject("invalid_records", status=422)
        recorded_steps = records.get("steps")
        requested_steps = request.get("steps")
        _validate_record_metadata(request, records)
        if _is_v2_request(request) and recorded_steps is None:
            reject("invalid_records", "provider did not return authoritative step records", status=422)
        if recorded_steps is not None:
            ordinals = [ordinal for step in recorded_steps for ordinal in step["command_ordinals"]]
            if ordinals != list(range(len(commands))) or len({step["id"] for step in recorded_steps}) != len(recorded_steps):
                reject("invalid_records", "step records do not partition commands", status=422)
            if requested_steps is not None and [
                    {key: step[key] for key in ("id", "label", "intent", "tags", "command_ordinals")}
                    for step in recorded_steps
                ] != [
                    {key: step[key] for key in ("id", "label", "intent", "tags", "command_ordinals")}
                    for step in requested_steps
                ]:
                reject("invalid_records", "provider step boundaries disagree with the request", status=422)
            from .timeline_commit_auth import validate
            source = self.revision_closure(request["project_id"], request["timeline_id"], prepared["expected_head"]["revision_id"])
            base = self.revision_closure(request["project_id"], request["timeline_id"], request["base_revision_id"])
            continuations = self._binding_continuations(request["project_id"], request["timeline_id"],
                                                       request["base_publication_id"], prepared["expected_head"])
            history = self._inverse_stage_history(request["project_id"], request["timeline_id"], records)
            validate(request, prepared, source, base, continuations, history)
        elif any("physical_ref" in binding for record in commands for binding in record["bindings"]):
            reject("invalid_records", "physical bindings require authoritative steps", status=422)
        for record in commands:
            if any(write["cause"] >= len(commands) for write in record["derived_writes"]):
                reject("invalid_records", status=422)
        undo_seqs = [self.history_entry(request["project_id"], request["timeline_id"], publication_id)["receipt"]["project_seq"][0]
                     for publication_id in records["undo_of"]]
        if undo_seqs != sorted(set(undo_seqs)):
            reject("invalid_records", "undo targets must follow acceptance order", status=422)
        restored = records["restored_from"]
        if restored is not None:
            source = self.revision_closure(request["project_id"], request["timeline_id"], restored["revision_id"])
            if source["parent_revision"]["content_digest"] != restored["content_digest"]:
                reject("invalid_records", status=422)
        for event in prepared["semantic_events"]:
            if event["command_ordinal"] >= len(commands) or self.validate_event is None:
                reject("invalid_event", status=422)
            self.validate_event(event)
        if inputs is not None and not has_materialization(prepared):
            inputs.validate(prepared)
        elif inputs is None and (document["dependency_manifest"]["documents"] or any(r["dependencies"] for r in commands)):
            reject("dependency_unavailable", "request-private dependency captures required")
        allocations = self._materializations(context, prepared, inputs)
        self._check_inherited_allocations(request["project_id"], request["timeline_id"], records, allocations)
        return {"canonical_document": document, "document_digest": prepared["document_digest"],
                "commands": [r["command"] for r in commands], "id_map": prepared["id_map"],
                "provider_version": prepared["provider_version"], "compiler_version": prepared["compiler_version"]}

    def _materializations(self, context, prepared, inputs):
        if has_materialization(prepared):
            from .timeline_commit_port import RequestCommitPort
            if not isinstance(inputs, RequestCommitPort) or canonical_json(inputs._provider_context()) != canonical_json(context):
                reject("dependency_unavailable", "request-private materialization captures required")
            return inputs.validate(prepared)
        return materialization_join(prepared, context["request"]["project_id"], context["request"]["timeline_id"],
                                    lambda _: reject("dependency_unavailable"))

    @staticmethod
    def _same_materialization_slot(shot, owner, allocation, prior_allocation, before, after):
        if allocation is None or allocation[0] != owner:
            return False
        pin = allocation[1]
        source = pin["source"]
        edge = [(o["shot_id"], o["shot_revision_id"]) for o in before["parent_revision"]["payload"]["occurrences"]
                if o["occurrence_id"] == owner]
        if edge != [(source["shot_id"], source["revision_id"])]:
            return False
        output = [o["shot_id"] for o in after["parent_revision"]["payload"]["occurrences"] if o["occurrence_id"] == owner]
        members = {i.get("item_id", i.get("id")) for s in after["shot_revisions"]
                   if s["shot_id"] == shot for i in s["payload"].get("items", [])}
        if output != [shot]:
            return False
        if prior_allocation is not None:
            return canonical_json(allocation) == canonical_json(prior_allocation)
        # Frozen M1 edges have no new allocation facts. Their already verified
        # source/binding/read proof remains usable only with this exact closure.
        return (canonical_json(pin["parent"]) == canonical_json({k: before["parent_revision"][k]
                                                                for k in ("revision_id", "content_digest")})
                and members == set(source["item_id_map"].values()))

    def _check_shot_destinations(self, context, prepared, inputs=None):
        # Check the wire shape before inspecting destinations. This preflight
        # precedes closure validation so foreign occupants get the same refusal.
        try:
            self.validate_prepared(prepared)
        except Exception:
            reject("invalid_prepared", "prepared commit does not satisfy the frozen schema", status=422)
        document, records = prepared["canonical_document"], prepared["records"]
        project, timeline = context["request"]["project_id"], context["request"]["timeline_id"]
        # Exact immutable reuse does not write the mutable shot projection.
        writes = [s for s in document["shot_revisions"] if self.conn.execute(
            "SELECT 1 FROM shot_revisions WHERE id=?", (s["revision_id"],)).fetchone() is None]
        if len({s["shot_id"] for s in writes}) != len(writes):
            reject("identity_collision")
        # Agent owns command.created consistency. Reserve the exact recorded
        # reference without interpreting command arguments or inventing ID forms.
        claims = [(item["kind"], item["ref"]) for record in records["commands"]
                  if record["command"]["op"] != "timeline.inverse" for item in record["created"]]
        claims = [(kind, self._reservation_identity(kind, ref)) for kind, ref in claims]
        if len(set(claims)) != len(claims):
            reject("identity_collision")
        self._check_birth_destinations(claims)
        occupied = set()
        for image in writes:
            row = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (image["shot_id"],)).fetchone()
            if row is not None:
                if row["project_id"] != project:
                    reject("destination_occupied")
                occupied.add(image["shot_id"])
        allocations = self._materializations(context, prepared, inputs)
        if not writes and not claims:
            return
        current = self.revision_closure(project, timeline, prepared["expected_head"]["revision_id"])
        owned = {s["shot_id"] for s in current["shot_revisions"]}
        fresh = {s["shot_id"] for s in writes} - owned
        for shot in fresh:
            for row in self.conn.execute("SELECT project_id FROM shot_revisions WHERE shot_id=?", (shot,)):
                if row["project_id"] != project:
                    reject("destination_occupied")
                occupied.add(shot)
        heads = {shot: self.conn.execute("SELECT revision_id FROM shot_revision_heads WHERE shot_id=? AND project_id=?",
                                        (shot, project)).fetchone() for shot in occupied}

        def unchanged(shot, revision):
            return heads[shot] is not None and heads[shot]["revision_id"] == revision

        authorized = set()
        for image in current["shot_revisions"]:
            shot = image["shot_id"]
            if shot in occupied and unchanged(shot, image["revision_id"]):
                # A film pin authorizes its own projection, not a newer catalog
                # head written since that pin was accepted.
                occupied.remove(shot)
                authorized.add(shot)
        restored_items = set()
        if occupied:
            from .timeline_commit_port import command_leaves

            requested = [p for c in command_leaves(context["request"]["commands"])
                         if c["op"] == "timeline.inverse" for p in c["args"]["publications"]]
            if requested != prepared["records"]["undo_of"]:
                reject("destination_occupied")

            def edges(value):
                return {o["occurrence_id"]: (o["shot_id"], o["shot_revision_id"])
                        for o in value["parent_revision"]["payload"]["occurrences"]}

            active, output = edges(current), edges(document)
            cursor, remaining = prepared["expected_head"], set(requested)
            while cursor and (occupied or remaining):
                # history_entry authenticates the records against the receipt/event.
                entry = self.history_entry(project, timeline, cursor["publication_id"])
                previous = entry["previous"]
                if entry["intent"] == "recorded":
                    before = self.revision_closure(project, timeline, previous["revision_id"])
                    prior = edges(before)
                    if entry["publication_id"] in remaining:
                        for o, (shot, _) in prior.items():
                            owner, source = "occurrence:" + o, before["parent_revision"]
                            if (shot in occupied and unchanged(shot, prior[o][1])
                                    and output.get(o, (None,))[0] == shot) and any(
                                    w["ref"] == "shot:" + shot or w["ref"] == owner or w["ref"].startswith(owner + "/")
                                    or (w["ref"] == "timeline" and not w["path"] and w["before"] == {
                                        "state": "present", "value": {k: source[k] for k in ("revision_id", "content_digest")}})
                                    for r in entry["records"]["commands"] for w in r["writes"]):
                                occupied.discard(shot)
                                authorized.add(shot)
                                restored_items.update(i.get("item_id", i.get("id"))
                                    for s in before["shot_revisions"] if s["shot_id"] == shot
                                    for i in s["payload"].get("items", []))
                        remaining.remove(entry["publication_id"])
                    accepted_document = self.revision_closure(project, timeline, entry["revision_id"])
                    after = edges(accepted_document)
                    historical = {**entry["receipt"]["result"], "records": entry["records"], "expected_head": previous}
                    prior_allocations = (materialization_join(historical, project, timeline,
                        lambda revision: self.revision_closure(project, timeline, revision))
                        if has_materialization(historical) else {})
                    for o, (shot, _) in after.items():
                        owner = "occurrence:" + o
                        if shot in allocations or shot in prior_allocations:
                            if not self._same_materialization_slot(shot, o, allocations.get(shot),
                                    prior_allocations.get(shot), before, accepted_document):
                                continue
                        if (shot in occupied and unchanged(shot, after[o][1])
                                and output.get(o, (None,))[0] == shot and o in prior
                                and active.get(o) == prior[o]
                                and any(any(b["ref"] == owner for b in r["bindings"])
                                        and any(read["ref"] == owner + "/shot" and read["path"] == ["shot_id"]
                                                and read["state"] == {"state": "present", "value": prior[o][0]}
                                                for read in r["reads"]) for r in entry["records"]["commands"])):
                            occupied.remove(shot)
                            authorized.add(shot)
                cursor = previous
            if occupied or remaining:
                reject("destination_occupied")
        destinations, fresh_items = {}, set()
        old_items = {s["shot_id"]: {i.get("item_id", i.get("id")) for i in s["payload"].get("items", [])}
                     for s in current["shot_revisions"]}
        for image in writes:
            shot = image["shot_id"]
            for item in image["payload"].get("items", []):
                identity = item.get("item_id", item.get("id"))
                if not identity or identity in destinations:
                    reject("identity_collision")
                destinations[identity] = shot
                if identity not in old_items.get(shot, set()):
                    fresh_items.add(identity)
        for identity, shot in destinations.items():
            row = self.conn.execute("SELECT shot_id FROM shot_items WHERE id=?", (identity,)).fetchone()
            if row is not None and (row["shot_id"] != shot or shot not in authorized):
                reject("identity_collision")
            for retained in self.conn.execute(
                    "SELECT DISTINCT s.* FROM shot_revisions s, json_each(s.payload_json, '$.items') i "
                    "WHERE COALESCE(json_extract(i.value, '$.item_id'), json_extract(i.value, '$.id'))=?", (identity,)):
                if (digest(json.loads(retained["payload_json"])) != retained["content_digest"]
                        or retained["project_id"] != project or retained["shot_id"] != shot or shot not in authorized):
                    reject("identity_collision")
        if not fresh and not fresh_items and not claims:
            return
        # Missing history cannot prove that a free ID was never reserved. Exact
        # matching records are authenticated against their durable receipt/event.
        if self.conn.execute("SELECT 1 FROM command_idempotency c LEFT JOIN timeline_commit_history h ON h.publication_id=c.txn_id "
                             "WHERE c.command_kind='timeline.commit' AND h.publication_id IS NULL LIMIT 1").fetchone():
            reject("identity_collision")
        reservations = set(claims) | {("shot", "shot:" + shot) for shot in fresh - authorized}
        reservations.update(("item", identity) for identity in fresh_items - restored_items)
        for kind, ref in reservations:
            rows = self.conn.execute(
                "SELECT DISTINCT h.* FROM timeline_commit_history h, "
                "json_each(h.records_json, '$.commands') r, json_each(r.value, '$.created') i "
                "WHERE json_extract(i.value, '$.kind')=? AND (json_extract(i.value, '$.ref')=? OR ?='item') "
                "AND (h.project_id=? OR ?='item') AND (h.timeline_id=? OR ? IN ('shot', 'item'))",
                (kind, ref, kind, project, kind, timeline, kind)).fetchall()
            for entry in rows:
                if kind == "item" and not any(i["kind"] == "item" and self._reservation_identity("item", i["ref"]) == ref
                        for r in json.loads(entry["records_json"])["commands"]
                        if r["command"]["op"] != "timeline.inverse" for i in r["created"]):
                    continue
                ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (entry["publication_id"],)).fetchone()
                if ledger is None:
                    reject("identity_collision")
                self._verify_accepted(ledger, entry)
                reject("identity_collision")

    @staticmethod
    def _reservation_identity(kind, ref):
        if kind == "item":
            member = item_identity(ref)
            if member is None:
                reject("invalid_records", "item reservation requires a canonical item ref", status=422)
            return member[1]
        if kind == "shot" and (root_identity(ref) is None or root_identity(ref)[0] != "shot"):
            reject("invalid_records", "shot reservation requires a canonical shot ref", status=422)
        return ref

    def _check_birth_destinations(self, claims):
        # Native births reserve even if a later command removes the new root.
        # Derived allocations never supply these claims; inverses were excluded.
        for kind, ref in claims:
            if kind == "shot":
                shot = root_identity(ref)[1]
                if (self.conn.execute("SELECT 1 FROM project_shots WHERE id=?", (shot,)).fetchone()
                        or self.conn.execute("SELECT 1 FROM shot_revisions WHERE shot_id=?", (shot,)).fetchone()):
                    reject("destination_occupied")
            elif kind == "item":
                if (self.conn.execute("SELECT 1 FROM shot_items WHERE id=?", (ref,)).fetchone()
                        or self.conn.execute("SELECT 1 FROM shot_revisions s, json_each(s.payload_json, '$.items') i "
                            "WHERE COALESCE(json_extract(i.value, '$.item_id'), json_extract(i.value, '$.id'))=? LIMIT 1", (ref,)).fetchone()):
                    reject("identity_collision")

    def preview(self, context, prepared, *, authorize, inputs=None):
        context, prepared = detached(context), detached(prepared)
        with self.store._mutex:
            authorize()
            if not context["request"].get("dry_run", False):
                reject("preview_requires_dry_run", status=422)
            self._check_context(context)
            self._check_head(context, prepared["expected_head"])
            self._check_shot_destinations(context, prepared, inputs)
            candidate = self._validate(context, prepared, inputs)
            request = context["request"]
            candidate["merge_mode"] = _effective_merge_mode(request)
            if "steps" in prepared["records"]:
                candidate["steps"] = prepared["records"]["steps"]
            base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
            return {"data": {"status": "preview", "would_status": "accepted" if prepared["expected_head"] == base else "merged",
                            "base_revision_id": request["base_revision_id"],
                            "base_publication_id": request["base_publication_id"],
                            "evaluated_head": prepared["expected_head"], **candidate}, "receipt": None}

    def _check_context(self, context):
        request = context["request"]
        realm = self._membership(request["project_id"], request["timeline_id"])
        if realm != context["realm_id"] or request_identity(context) != context["request_hash"]:
            reject("invocation_mismatch", status=422)
        if context["invocation"]["operation"] == "commitTimeline" and request != context["invocation"]["body"]:
            reject("invocation_mismatch", status=422)
        if self.history_entry(request["project_id"], request["timeline_id"], request["base_publication_id"])["revision_id"] != request["base_revision_id"]:
            reject("history_unavailable")

    def _check_head(self, context, expected):
        from .timeline_commit import StaleHead

        request = context["request"]
        current = self.head(request["project_id"], request["timeline_id"])
        if current != expected:
            raise StaleHead(current)
        base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
        if any(c["op"] == "timeline.restore" for c in request["commands"]) and expected != base:
            reject("stale_head")

    def accept(self, context, prepared, *, authorize, inputs=None):
        context, prepared = detached(context), detached(prepared)
        with self.store._mutex:
            if self.conn.in_transaction:
                raise ProtocolError("commit acceptance requires the outer transaction")
            with self.store._transaction():
                authorize()
                replay = self._lookup(context)
                if replay is not None:
                    return replay
                if context["request"].get("dry_run", False):
                    reject("dry_run_accept", status=422)
                self._check_context(context)
                self._check_head(context, prepared["expected_head"])
                self._check_shot_destinations(context, prepared, inputs)
                candidate = self._validate(context, prepared, inputs)
                request, previous = context["request"], prepared["expected_head"]
                from .timeline_commit_reference_projection import (
                    ReferenceProjectionError,
                    prepare_reference_projection,
                )
                try:
                    previous_document = self.revision_closure(
                        request["project_id"], request["timeline_id"], previous["revision_id"]
                    )
                    timeline = self.conn.execute(
                        "SELECT version FROM timelines WHERE id=? AND project_id=?",
                        (request["timeline_id"], request["project_id"]),
                    ).fetchone()
                    reference_projection = prepare_reference_projection(
                        self.conn, candidate["canonical_document"], previous_document,
                        next_version=int(timeline["version"]) + 1,
                    )
                except ReferenceProjectionError as exc:
                    reject(exc.reason, exc.message, status=exc.status)
                base = {"revision_id": request["base_revision_id"], "publication_id": request["base_publication_id"]}
                modern = _is_v2_request(request, prepared["records"])
                data = {"status": ("accepted" if previous == base else ("merged" if modern else "rebased")),
                        "base_revision_id": base["revision_id"],
                        "base_publication_id": base["publication_id"], "previous_revision_id": previous["revision_id"],
                        "previous_publication_id": previous["publication_id"],
                        "accepted_revision_id": candidate["canonical_document"]["parent_revision"]["revision_id"],
                        "rebased_onto": None if previous == base else previous, **candidate,
                        "publisher": context["publisher"],
                        **{k: request[k] for k in _METADATA if k in request}}
                if modern:
                    data["merge_mode"] = _effective_merge_mode(request)
                    data.setdefault("label", "Timeline edit")
                if modern and "steps" in prepared["records"]:
                    data["steps"] = prepared["records"]["steps"]
                self._persist_closure(candidate["canonical_document"])
                result = self._publish(context, data, previous, prepared["records"], prepared["semantic_events"])
                from .timeline_commit_reference_projection import (
                    apply_reference_projection,
                )
                if reference_projection is not None:
                    apply_reference_projection(self.conn, reference_projection)
                self._project_text_bindings(candidate["canonical_document"], prepared["records"], result["receipt"]["receipt_id"])
                if inputs is not None:
                    inputs.persist(prepared, result["receipt"]["receipt_id"], data["accepted_revision_id"])
                return result

    def _project_text_bindings(self, document, records, publication_id):
        """Derive live text-binding rows and events from the accepted recorder's writes.

        Runs in the acceptance transaction after _persist_closure; only this commit's
        writes are projected, so historical reuse never repoints a live row.
        """
        project_id = document["project_id"]
        shots = {o["occurrence_id"]: o["shot_id"] for o in document["parent_revision"]["payload"]["occurrences"]}
        for record in records["commands"]:
            for write in record["writes"]:
                if "/text-binding:" not in write["ref"]:
                    continue
                match = _TEXT_BINDING_REF.fullmatch(write["ref"])
                if match is None or write["path"]:
                    reject("invalid_records", "malformed text binding write", status=422)
                occurrence, kind, slot = match.groups()
                owner = "occurrence:" + occurrence
                read = next((r for r in record["reads"] if r["ref"] == owner + "/shot" and r["path"] == ["shot_id"]), None)
                shot_id = shots.get(occurrence)
                if shot_id is None or read is None or read["state"] != {"state": "present", "value": shot_id}:
                    reject("text_binding_owner_changed", "text binding owner differs from the accepted shot")
                self._project_text_binding(project_id, shot_id, kind, slot, write["before"], write["after"], publication_id)

    def _project_text_binding(self, project_id, shot_id, kind, slot, before, after, publication_id):
        from .service import RuntimeService
        from .timeline_commit_port import verify_retained_text_object, verify_text_object
        from .cas import ContentAddressedStore

        owner = self.conn.execute("SELECT project_id FROM project_shots WHERE id=?", (shot_id,)).fetchone()
        if owner is None or owner["project_id"] != project_id:
            reject("dependency_unavailable", "text binding shot is not in this project")
        binding_id = RuntimeService._text_binding_id(project_id, shot_id, kind, slot)
        row = self.conn.execute("SELECT * FROM shot_text_bindings WHERE id=? AND project_id=?", (binding_id, project_id)).fetchone()
        latest = None
        if row is not None:
            events = RuntimeService._text_binding_events(self.conn, row)
            latest = json.loads(events[-1]["payload_json"])
        live = latest is not None and latest.get("state", "present") == "present"
        current = None
        if live:
            media = self.conn.execute("SELECT size, media_type FROM objects WHERE digest=?", (row["media_digest"],)).fetchone()
            if media is None:
                reject("dependency_unavailable", "bound text media is missing")
            current = {"kind": row["kind"], "slot": row["slot"], "media_id": "sha256:" + row["media_digest"],
                       "content_hash": "sha256:" + row["media_digest"], "byte_size": media["size"], "mime_type": media["media_type"]}
        fields = ("kind", "slot", "media_id", "content_hash", "byte_size", "mime_type")
        if (before["state"] == "present") != live or (live and any(
                before["value"].get(field) != current[field] for field in fields)):
            reject("text_binding_mismatch", "recorded text binding state differs from the live binding")
        clearing = after["state"] == "absent"
        if clearing and not live:
            reject("text_binding_mismatch", "cannot clear an absent text binding")
        value = current if clearing else after["value"]
        for descriptor in ([current] if live else []) + ([] if clearing else [value]):
            selection = {"object_id": descriptor.get("media_id"), "digest": descriptor.get("content_hash"),
                         "size": descriptor.get("byte_size"), "media_type": descriptor.get("mime_type")}
            if (descriptor.get("kind"), descriptor.get("slot")) != (kind, slot):
                reject("invalid_records", "text binding row differs from its key", status=422)
            cas = ContentAddressedStore(self.store.cas_root)
            if selection["media_type"] == "text/plain" and row is not None:
                verify_retained_text_object(self.conn, cas, row, selection)
            else:
                verify_text_object(self.conn, cas, project_id, selection)
        object_digest = value["media_id"][7:]
        timestamp = now()
        if row is None:
            self.conn.execute("INSERT INTO shot_text_bindings(id, project_id, shot_id, kind, slot, media_digest, event_stream_id, head_seq, created_at, updated_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?)",
                              (binding_id, project_id, shot_id, kind, slot, object_digest, binding_id + ":shot.text_binding", timestamp, timestamp))
            head, previous_hash = 0, ""
        elif live and not clearing and row["media_digest"] == object_digest:
            return
        else:
            head = row["head_seq"]
            previous_hash = self.conn.execute("SELECT event_hash FROM shot_text_binding_events WHERE binding_id=? AND seq=?",
                                              (binding_id, head)).fetchone()["event_hash"]
        event_id, seq = new_id(), head + 1
        event_kind = "shot.text_binding.created" if seq == 1 else "shot.text_binding.rebound"
        payload = {"binding_id": binding_id, "project_id": project_id, "shot_id": shot_id, "kind": kind, "slot": slot,
                   "media_id": value["media_id"], "content_hash": value["content_hash"], "byte_size": value["byte_size"],
                   "mime_type": value["mime_type"], "publication_id": publication_id,
                   "state": "absent" if clearing else "present"}
        event_hash = hashlib.sha256(canonical_json({"event_id": event_id, "binding_id": binding_id, "seq": seq,
                                                    "kind": event_kind, "payload": payload,
                                                    "previous_hash": previous_hash}).encode()).hexdigest()
        self.conn.execute("INSERT INTO shot_text_binding_events(event_id, binding_id, project_id, seq, kind, payload_json, previous_hash, event_hash, created_at) "
                          "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                          (event_id, binding_id, project_id, seq, event_kind, canonical_json(payload), previous_hash, event_hash, timestamp))
        self.conn.execute("UPDATE shot_text_bindings SET media_digest=?, head_seq=?, updated_at=? WHERE id=?",
                          (object_digest, seq, timestamp, binding_id))

    def _persist_closure(self, document):
        project_id, timestamp = document["project_id"], now()
        for image in document["internal_timeline_revisions"]:
            self.conn.execute("INSERT OR IGNORE INTO internal_timeline_revisions(id, project_id, timeline_id, payload_json, content_digest, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?)", (image["revision_id"], project_id, image["timeline_id"], canonical_json(image["payload"]), image["content_digest"], timestamp))
        for image in document["shot_revisions"]:
            existing = self.conn.execute("SELECT 1 FROM shot_revisions WHERE id=?", (image["revision_id"],)).fetchone()
            if existing:
                continue
            payload, shot_id = image["payload"], image["shot_id"]
            self.conn.execute("INSERT INTO project_shots(id, project_id, name, metadata_json, version, created_at, updated_at, archived_at) "
                              "VALUES (?, ?, ?, ?, 1, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name=excluded.name, metadata_json=excluded.metadata_json, "
                              "version=project_shots.version+1, updated_at=excluded.updated_at, archived_at=excluded.archived_at",
                              (shot_id, project_id, payload.get("name") or shot_id, canonical_json(payload.get("metadata", {})), timestamp, timestamp,
                               timestamp if payload.get("archived", False) else None))
            self.conn.execute("DELETE FROM shot_items WHERE shot_id=?", (shot_id,))
            for ordinal, item in enumerate(payload.get("items", [])):
                self.conn.execute("INSERT INTO shot_items(id, shot_id, media_id, sort_key, source_frame, metadata_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
                                  (item.get("item_id", item.get("id")), shot_id, item["media_id"].removeprefix("sha256:"), f"{ordinal:08d}",
                                   item.get("source_frame"), canonical_json(item.get("metadata", {})), timestamp))
            self.conn.execute("INSERT INTO shot_revisions(id, project_id, shot_id, internal_timeline_revision_id, payload_json, content_digest, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?)", (image["revision_id"], project_id, shot_id, image["internal_timeline_revision_id"],
                                                             canonical_json(payload), image["content_digest"], timestamp))
            self.conn.execute("INSERT INTO shot_revision_heads(shot_id, project_id, revision_id, updated_at) VALUES (?, ?, ?, ?) "
                              "ON CONFLICT(shot_id) DO UPDATE SET revision_id=excluded.revision_id, updated_at=excluded.updated_at",
                              (shot_id, project_id, image["revision_id"], timestamp))
        parent, manifest = document["parent_revision"], document["dependency_manifest"]
        existing = self.conn.execute("SELECT 1 FROM parent_composition_revisions WHERE id=?", (parent["revision_id"],)).fetchone()
        if existing is None:
            self.conn.execute("INSERT INTO parent_composition_revisions(id, project_id, timeline_id, payload_json, content_digest, commit_manifest_json, created_at) "
                              "VALUES (?, ?, ?, ?, ?, ?, ?)", (parent["revision_id"], project_id, document["timeline_id"], canonical_json(parent["payload"]),
                                                             parent["content_digest"], canonical_json(manifest), timestamp))
            for ordinal, occurrence in enumerate(parent["payload"]["occurrences"]):
                self.conn.execute("INSERT INTO composition_revision_occurrences(parent_revision_id, occurrence_id, ordinal, project_id, shot_id, shot_revision_id, "
                                  "placement_json, source_offset_json, duration_ms, speed_json, track, transform_json, gain, muted, provenance_json) "
                                  "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                                  (parent["revision_id"], occurrence["occurrence_id"], ordinal, project_id, occurrence["shot_id"], occurrence["shot_revision_id"],
                                   canonical_json(occurrence["placement"]), canonical_json(occurrence.get("source_offset", 0)), occurrence["duration_ms"],
                                   canonical_json(occurrence.get("speed", 1)), occurrence["track"], canonical_json(occurrence.get("transform", {})), occurrence.get("gain", 1),
                                   int(occurrence.get("muted", occurrence.get("mute", False))), canonical_json(occurrence.get("provenance", {}))))
            dependencies = [("shot_revision", p["revision_id"], p["content_digest"]) for p in manifest["shots"]]
            dependencies += [("internal_timeline_revision", p["revision_id"], p["content_digest"]) for p in manifest["internal_timelines"]]
            dependencies += [("media", p["media_id"], p["content_digest"]) for p in manifest["media"]]
            for ordinal, (kind, identity, content_digest) in enumerate(dependencies):
                self.conn.execute("INSERT INTO composition_revision_dependencies VALUES (?, ?, ?, ?, ?)",
                                  (parent["revision_id"], kind, identity, content_digest, ordinal))
        else:
            self.conn.execute("UPDATE parent_composition_revisions SET commit_manifest_json=? WHERE id=? AND commit_manifest_json IS NULL",
                              (canonical_json(manifest), parent["revision_id"]))

    def _publish(self, context, data, previous, records, semantic_events):
        request = context["request"]
        project_id, timeline_id = request["project_id"], request["timeline_id"]
        revision_id = data["canonical_document"]["parent_revision"]["revision_id"]
        event_ids = []
        for event in semantic_events:
            event_ids.append(self.store._append_timeline_event(timeline_id, event["kind"],
                {"project_id": project_id, "timeline_id": timeline_id, "publisher": context["publisher"], **event}))
        event_ids.append(self.store._append_timeline_event(timeline_id, "timeline.commit.accepted",
            {"project_id": project_id, "timeline_id": timeline_id, "previous": previous, "revision_id": revision_id,
             "publisher": context["publisher"], "intent": "recorded", "records_digest": digest(records)}))
        seq = self.conn.execute("SELECT COUNT(*) FROM timeline_events WHERE timeline_id=?", (timeline_id,)).fetchone()[0]
        publication_id = self.store._record_command_receipt("timeline.commit", scope(context), context["idempotency_key"], context["request_hash"],
            data, project_id=project_id, event_ids=event_ids, primary_stream_id=timeline_id, resulting_stream_seq=seq)
        ledger = self.conn.execute("SELECT * FROM command_idempotency WHERE txn_id=?", (publication_id,)).fetchone()
        metadata = _history_metadata(request, data)
        self.conn.execute("INSERT INTO timeline_commit_history VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (publication_id, project_id, timeline_id, revision_id, previous["publication_id"] if previous else None,
             previous["revision_id"], "recorded", canonical_json(records),
             canonical_json(metadata), data.get("provider_version"), data.get("compiler_version"),
             context["publisher"], ledger["first_project_seq"]))
        changed = self.conn.execute("UPDATE parent_composition_heads SET revision_id=?, publication_id=?, updated_at=? "
            "WHERE project_id=? AND timeline_id=? AND revision_id=? AND publication_id=?", (revision_id, publication_id, now(), project_id, timeline_id,
            previous["revision_id"], previous["publication_id"])).rowcount
        if changed != 1:
            raise ProtocolError("head changed inside acceptance transaction")
        self.conn.execute("UPDATE timelines SET version=version+1 WHERE id=? AND project_id=?", (timeline_id, project_id))
        return self._envelope(ledger, project_id)

    def _install_entries(self, project_id, timeline_id, plan):
        for entry in plan["entries"]:
            previous = entry["previous"]
            self.conn.execute("INSERT INTO timeline_commit_history VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (entry["publication_id"], project_id, timeline_id, entry["revision_id"],
                 previous["publication_id"] if previous else None, previous["revision_id"] if previous else None,
                 entry["intent"], None, canonical_json({k: entry[k] for k in _METADATA if k in entry}),
                 entry["provider_version"], entry["compiler_version"], entry["publisher"], entry["receipt"]["project_seq"][0]))
        changed = self.conn.execute("UPDATE parent_composition_heads SET publication_id=? WHERE project_id=? AND timeline_id=? "
                                   "AND revision_id=? AND publication_id IS NULL", (plan["head"]["publication_id"], project_id,
                                   timeline_id, plan["head"]["revision_id"])).rowcount
        if changed != 1:
            reject("stale_head")

    def install_verified_baseline(self, project_id, timeline_id, *, authorize):
        from .cas import ContentAddressedStore
        from .timeline_commit_baseline import baseline_install_plan, verify_baseline

        with self.store._mutex, self.store._transaction():
            authorize()
            self._membership(project_id, timeline_id)
            current = self.conn.execute("SELECT revision_id, publication_id FROM parent_composition_heads WHERE project_id=? AND timeline_id=?",
                                        (project_id, timeline_id)).fetchone()
            if current is not None and current["publication_id"]:
                return self.head(project_id, timeline_id)
            read_object = ContentAddressedStore(self.store.cas_root).read
            facts = verify_baseline(self.conn, project_id, timeline_id, read_object=read_object)
            plan = baseline_install_plan(self.conn, facts, read_object=read_object)
            document = facts["canonical_document"]
            self._validate_closure(document)
            for entry in plan["entries"]:
                event = self.conn.execute("SELECT payload_json FROM timeline_events WHERE id=? AND timeline_id=?",
                                          (entry["receipt"]["event_ids"][0], timeline_id)).fetchone()
                manifest = {**json.loads(event[0])["dependency_manifest"], "documents": []}
                self.conn.execute("UPDATE parent_composition_revisions SET commit_manifest_json=? WHERE id=? AND commit_manifest_json IS NULL",
                                  (canonical_json(manifest), entry["revision_id"]))
            self._install_entries(project_id, timeline_id, plan)
            return detached(plan["head"])

    def adopt_empty_shell(self, project_id, timeline_id, *, authorize):
        """Bootstrap an empty headless shell or adopt its verified publication.

        A shell without a parent must have no retained parent or publication.
        Returns the publication event installed by the existing bootstrap path.
        """
        from .cas import ContentAddressedStore
        from .timeline_commit_baseline import bootstrap_install_plan

        with self.store._mutex, self.store._transaction():
            authorize()
            self._membership(project_id, timeline_id)
            current = self.conn.execute("SELECT project_id, revision_id, publication_id FROM parent_composition_heads WHERE timeline_id=?",
                                        (timeline_id,)).fetchone()
            if current is not None and (current["project_id"] != project_id or current["publication_id"] is not None):
                reject("history_unavailable")
            if not timeline_scope_is_empty(self.conn, timeline_id, project_id=project_id):
                reject("history_unavailable")
            if current is None or current["revision_id"] is None:
                if self.conn.execute("SELECT 1 FROM parent_composition_revisions WHERE timeline_id=? LIMIT 1", (timeline_id,)).fetchone():
                    reject("history_unavailable")
                # Normal create retains its empty legacy projection as well.
                empty_legacy = {"shots": [], "references": []}
                for row in self.conn.execute("SELECT * FROM internal_timeline_revisions WHERE timeline_id=?", (timeline_id,)):
                    if row["project_id"] != project_id or row["payload_json"] != canonical_json(empty_legacy) or row["content_digest"] != digest(empty_legacy):
                        reject("history_unavailable")
                if self.conn.execute("SELECT 1 FROM command_idempotency WHERE command_kind='parent_composition.publish' AND aggregate_id=? LIMIT 1",
                                     (timeline_id,)).fetchone() or self.conn.execute(
                        "SELECT 1 FROM timeline_events WHERE timeline_id=? AND kind='parent.composition.published' LIMIT 1", (timeline_id,)).fetchone():
                    reject("history_unavailable")
                head = self.bootstrap(project_id, timeline_id, authorize=authorize)
                entry = self.history_entry(project_id, timeline_id, head["publication_id"])
                return entry["receipt"]["event_ids"][0]
            plan = bootstrap_install_plan(self.conn, project_id, timeline_id,
                                          read_object=ContentAddressedStore(self.store.cas_root).read)
            self._install_entries(project_id, timeline_id, plan)
            return plan["entries"][0]["receipt"]["event_ids"][0]

    def bootstrap(self, project_id, timeline_id, *, authorize):
        from .cas import ContentAddressedStore
        from .timeline_commit_baseline import bootstrap_install_plan, empty_bootstrap_document

        # May compose with main's atomic create transaction. This is the sole
        # exception to accept's outer-transaction requirement.
        with self.store._mutex, self.store._transaction():
            authorize()
            self._membership(project_id, timeline_id)
            current = self.conn.execute("SELECT revision_id, publication_id FROM parent_composition_heads WHERE project_id=? AND timeline_id=?",
                                        (project_id, timeline_id)).fetchone()
            if current is not None and current["revision_id"]:
                if current["publication_id"]:
                    return self.head(project_id, timeline_id)
                reject("history_unavailable")
            document = empty_bootstrap_document(project_id, timeline_id, "bootstrap-" + new_id())
            self._validate_closure(document)
            self._persist_closure(document)
            parent, timestamp = document["parent_revision"], now()
            manifest = {k: v for k, v in document["dependency_manifest"].items() if k != "documents"}
            self.conn.execute("INSERT INTO parent_composition_heads(timeline_id, project_id, revision_id, updated_at) VALUES (?, ?, ?, ?) "
                              "ON CONFLICT(timeline_id) DO UPDATE SET revision_id=excluded.revision_id, updated_at=excluded.updated_at",
                              (timeline_id, project_id, parent["revision_id"], timestamp))
            event = self.store._append_timeline_event(timeline_id, "parent.composition.published",
                {"project_id": project_id, "timeline_id": timeline_id, "old_head": None, "new_head": parent["revision_id"],
                 "content_digest": parent["content_digest"], "dependency_manifest": manifest})
            result = {"project_id": project_id, "timeline_id": timeline_id, "revision_id": parent["revision_id"],
                      "parent_revision_id": parent["revision_id"], "content_digest": parent["content_digest"], "payload": parent["payload"],
                      "old_head": None, "new_head": parent["revision_id"], "dependency_manifest": manifest,
                      "content_digests": {"parent": parent["content_digest"]}, "event_id": event, "created_at": timestamp}
            event_seq = self.conn.execute("SELECT COUNT(*) FROM timeline_events WHERE timeline_id=?", (timeline_id,)).fetchone()[0]
            self.store._record_command_receipt("parent_composition.publish", timeline_id, "bootstrap:" + timeline_id,
                digest({"project_id": project_id, "timeline_id": timeline_id, "bootstrap": True})[7:], result,
                project_id=project_id, event_ids=[event], primary_stream_id=timeline_id, resulting_stream_seq=event_seq, created_at=timestamp)
            plan = bootstrap_install_plan(self.conn, project_id, timeline_id,
                                          read_object=ContentAddressedStore(self.store.cas_root).read)
            self._install_entries(project_id, timeline_id, plan)
            return detached(plan["head"])

